package pigeon;

import pigeon.util.WorldUtils;
import org.junit.jupiter.api.extension.ExtensionContext;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.ArgumentsProvider;
import org.junit.jupiter.params.provider.ArgumentsSource;

import java.util.Set;
import java.util.stream.Stream;
import java.util.EnumSet;

import net.runelite.api.WorldType;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class IgnoredWorldTest {
    @ParameterizedTest(name = "World should not be ignored {0}")
    @ArgumentsSource(NonIgnoredWorldTypeProvider.class)
    void worldShouldNotBeIgnored(Set<WorldType> worldType) {
        assertFalse(WorldUtils.isIgnoredWorld(worldType));
    }

    private static class NonIgnoredWorldTypeProvider implements ArgumentsProvider {
        @Override
        public Stream<? extends Arguments> provideArguments(ExtensionContext context) {
            return Stream.of(
                Arguments.of(EnumSet.of(WorldType.MEMBERS)),
                Arguments.of(EnumSet.noneOf(WorldType.class)),
                Arguments.of(EnumSet.of(WorldType.SKILL_TOTAL)),
                Arguments.of(EnumSet.of(WorldType.FRESH_START_WORLD))
            );
        }
    }

    @ParameterizedTest(name = "World should be ignored {0}")
    @ArgumentsSource(IgnoredWorldTypeProvider.class)
    void worldShouldBeIgnored(Set<WorldType> worldType) {
        assertTrue(WorldUtils.isIgnoredWorld(worldType));
    }

    private static class IgnoredWorldTypeProvider implements ArgumentsProvider {
        @Override
        public Stream<? extends Arguments> provideArguments(ExtensionContext context) {
            return Stream.of(
                Arguments.of(EnumSet.of(WorldType.PVP_ARENA)),
                Arguments.of(EnumSet.of(WorldType.QUEST_SPEEDRUNNING)),
                Arguments.of(EnumSet.of(WorldType.NOSAVE_MODE)),
                Arguments.of(EnumSet.of(WorldType.TOURNAMENT_WORLD)),
                Arguments.of(EnumSet.of(WorldType.FRESH_START_WORLD, WorldType.NOSAVE_MODE))
            );
        }
    }
}

package pigeon;

import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PigeonConfigVisibilityTest {
    @Test
    void profileOwnedSettingsAreHiddenFromRuneLiteConfigPanel() {
        List<String> visibleItems = Arrays.stream(PigeonConfig.class.getDeclaredMethods())
            .map(method -> new ConfigMethod(method, method.getAnnotation(ConfigItem.class)))
            .filter(configMethod -> configMethod.item != null && !configMethod.item.hidden())
            .map(configMethod -> configMethod.method.getName())
            .sorted()
            .collect(Collectors.toList());

        assertEquals(List.of("showPanelIcon"), visibleItems,
            "Only global interface settings should appear in the generic RuneLite config panel");

        List<String> visibleSections = Arrays.stream(PigeonConfig.class.getDeclaredFields())
            .filter(field -> field.getAnnotation(ConfigSection.class) != null)
            .map(field -> field.getName())
            .sorted()
            .collect(Collectors.toList());

        assertTrue(visibleSections.isEmpty(),
            "The generic RuneLite config panel must not render empty profile sections: " + visibleSections);
    }

    private static final class ConfigMethod {
        private final Method method;
        private final ConfigItem item;

        private ConfigMethod(Method method, ConfigItem item) {
            this.method = method;
            this.item = item;
        }
    }
}

package pigeon.ui;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;

class PigeonIconTest {
    @Test
    void pluginHubIconMatchesPigeonArtwork() throws IOException {
        BufferedImage expected = PigeonIcon.create(48);
        BufferedImage actual = ImageIO.read(new File("icon.png"));

        assertEquals(48, actual.getWidth());
        assertEquals(48, actual.getHeight());
        for (int y = 0; y < expected.getHeight(); y++) {
            for (int x = 0; x < expected.getWidth(); x++) {
                assertEquals(expected.getRGB(x, y), actual.getRGB(x, y),
                    "Plugin Hub icon differs at (" + x + ", " + y + ")");
            }
        }
    }
}

package pigeon.message.templating;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class TemplateTest {

    @Test
    void noReplacements() {
        assertEquals(
            "Hello world!",
            Template.builder()
                .template("Hello world!")
                .build()
                .evaluate(true)
        );
    }

    @Test
    void noReplacementsFast() {
        assertEquals(
            "Hello world!",
            Template.builder()
                .template("Hello world!")
                .replacementBoundary("%")
                .build()
                .evaluate(true)
        );
    }

    @Test
    void unusedReplacements() {
        assertEquals(
            "Hello world!",
            Template.builder()
                .template("Hello world!")
                .replacement("%PLANET%", Replacements.ofText("Earth"))
                .build()
                .evaluate(true)
        );
    }

    @Test
    void unusedReplacementsFast() {
        assertEquals(
            "Hello world!",
            Template.builder()
                .template("Hello world!")
                .replacementBoundary("%")
                .replacement("%PLANET%", Replacements.ofText("Earth"))
                .build()
                .evaluate(true)
        );
    }

    @Test
    void withReplacements() {
        assertEquals(
            "dank dank has killed Monk",
            Template.builder()
                .template("%USERNAME% has killed %TARGET%")
                .replacement("%USERNAME%", Replacements.ofText("dank dank"))
                .replacement("%TARGET%", Replacements.ofWiki("Monk"))
                .build()
                .evaluate(false)
        );
    }

    @Test
    void withReplacementsFast() {
        assertEquals(
            "dank dank has killed Monk",
            Template.builder()
                .template("%USERNAME% has killed %TARGET%")
                .replacementBoundary("%")
                .replacement("%USERNAME%", Replacements.ofText("dank dank"))
                .replacement("%TARGET%", Replacements.ofWiki("Monk"))
                .build()
                .evaluate(false)
        );
    }

    @Test
    void withRichReplacements() {
        assertEquals(
            "dank dank has killed [Monk](https://oldschool.runescape.wiki/w/Special:Search?search=Monk)",
            Template.builder()
                .template("%USERNAME% has killed %TARGET%")
                .replacement("%USERNAME%", Replacements.ofText("dank dank"))
                .replacement("%TARGET%", Replacements.ofWiki("Monk"))
                .build()
                .evaluate(true)
        );
    }

    @Test
    void withRichReplacementsFast() {
        assertEquals(
            "dank dank has killed [Monk](https://oldschool.runescape.wiki/w/Special:Search?search=Monk)",
            Template.builder()
                .template("%USERNAME% has killed %TARGET%")
                .replacementBoundary("%")
                .replacement("%USERNAME%", Replacements.ofText("dank dank"))
                .replacement("%TARGET%", Replacements.ofWiki("Monk"))
                .build()
                .evaluate(true)
        );
    }

    @Test
    void missingReplacements() {
        assertEquals(
            "%USERNAME% has killed Monk",
            Template.builder()
                .template("%USERNAME% has killed %TARGET%")
                .replacement("%TARGET%", Replacements.ofWiki("Monk"))
                .build()
                .evaluate(false)
        );
    }

    @Test
    void missingReplacementsFast() {
        assertEquals(
            "%USERNAME% has killed Monk",
            Template.builder()
                .template("%USERNAME% has killed %TARGET%")
                .replacementBoundary("%")
                .replacement("%TARGET%", Replacements.ofWiki("Monk"))
                .build()
                .evaluate(false)
        );
    }

    @Test
    void withRichLink() {
        assertEquals(
            "dank dank has pk'd [Forsen](https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1=Forsen)",
            Template.builder()
                .template("%USERNAME% has pk'd %TARGET%")
                .replacement("%USERNAME%", Replacements.ofText("dank dank"))
                .replacement("%TARGET%", Replacements.ofLink("Forsen", "https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1=Forsen"))
                .build()
                .evaluate(true)
        );
    }

    @Test
    void withRichLinkFast() {
        assertEquals(
            "dank dank has pk'd [Forsen](https://secure.runescape.com/m=hiscore_oldschool/hiscorepersonal?user1=Forsen)",
            Template.builder()
                .template("%USERNAME% has pk'd %TARGET%")
