    static {
        Map<KitType, SerializedItemStack> m = new EnumMap<>(KitType.class);
        m.put(KitType.WEAPON, new SerializedItemStack(ItemID.STAFF_OF_ZAROS, 1, WEAPON_PRICE, "Ancient staff"));
