    @Test
    void testNotifyInterval() {
        // more mocks
        when(config.killCountNotifyInitial()).thenReturn(false);
        when(config.killCountInterval()).thenReturn(70);
        when(configManager.getRSProfileConfiguration("personalbest", "king black dragon", double.class)).thenReturn(29.6);

        // fire event
        String gameMessage = "Your King Black Dragon kill count is: 420.";
        notifier.onGameMessage(gameMessage);
        notifier.onTick();

        // check notification
        NotificationBody<BossNotificationData> body = NotificationBody.<BossNotificationData>builder()
            .text(buildTemplate("King Black Dragon", 420))
            .extra(new BossNotificationData("King Black Dragon", 420, gameMessage, null, null, Duration.ofSeconds(29).plusMillis(600), null))
            .playerName(PLAYER_NAME)
            .type(NotificationType.KILL_COUNT)
            .build();

        verifyCreateMessage(
            PRIMARY_WEBHOOK_URL,
            true,
            body
        );

        assertDoesNotThrow(() -> RuneLiteAPI.GSON.toJson(body));
    }

    @Test
    void testNotifyTwoProfilesFromOneParsedKill() {
        PigeonProfile clan = killCountProfile(
            "Clan", true, 70, "Clan: %BOSS% at %COUNT%", "https://example.com/clan");
        PigeonProfile friends = killCountProfile(
            "Friends", true, 60, "Friends: %BOSS% at %COUNT%", "https://example.com/friends");
        PigeonProfile disabled = killCountProfile(
            "Disabled", false, 1, "Disabled", "https://example.com/disabled");
        mockStoredProfiles(clan, friends, disabled);

        notifier.onGameMessage("Your King Black Dragon kill count is: 420.");
        notifier.onTick();

        ArgumentCaptor<PigeonConfig> configs = ArgumentCaptor.forClass(PigeonConfig.class);
        ArgumentCaptor<String> urls = ArgumentCaptor.forClass(String.class);
        ArgumentCaptor<NotificationBody> bodies = ArgumentCaptor.forClass(NotificationBody.class);
        verify(messageHandler, times(2)).createMessage(
            configs.capture(), urls.capture(), anyBoolean(), bodies.capture());

        org.junit.jupiter.api.Assertions.assertEquals(
            List.of("https://example.com/clan", "https://example.com/friends"), urls.getAllValues());
        org.junit.jupiter.api.Assertions.assertEquals(
            "Clan: King Black Dragon at 420", bodies.getAllValues().get(0).getText().evaluate(false));
        org.junit.jupiter.api.Assertions.assertEquals(
            "Friends: King Black Dragon at 420", bodies.getAllValues().get(1).getText().evaluate(false));
    }

