    private static Template buildTemplate(String boss, int count) {
        return Template.builder()
            .template(PLAYER_NAME + " has defeated {{boss}} with a completion count of " + count)
            .replacement("{{boss}}", Replacements.ofWiki(boss))
            .build();
    }

    private PigeonProfile killCountProfile(String name, boolean enabled, int interval,
                                           String message, String webhook) {
        return PigeonProfile.builder()
            .schemaVersion(PigeonProfile.CURRENT_SCHEMA_VERSION)
            .id(UUID.randomUUID())
            .name(name)
            .enabled(enabled)
            .settings(Map.of(
                "killCountEnabled", new JsonPrimitive(true),
                "killCountSendImage", new JsonPrimitive(false),
                "killCountInitial", new JsonPrimitive(false),
                "killCountPB", new JsonPrimitive(false),
                "killCountInterval", new JsonPrimitive(interval),
                "killCountMessage", new JsonPrimitive(message)
            ))
            .webhooks(new ProfileWebhooks(List.of(webhook), Map.of()))
            .build();
    }

    private void mockStoredProfiles(PigeonProfile... profiles) {
        profileRuntimeService.invalidate();
        List<UUID> ids = java.util.Arrays.stream(profiles)
            .map(PigeonProfile::getId)
            .collect(java.util.stream.Collectors.toList());
        when(configManager.getConfiguration(ConfigProfileRepository.CONFIG_GROUP, ConfigProfileRepository.INDEX_KEY))
            .thenReturn(gson.toJson(ids));
        for (PigeonProfile profile : profiles) {
            when(configManager.getConfiguration(
                ConfigProfileRepository.CONFIG_GROUP, "profile_" + profile.getId()))
                .thenReturn(gson.toJson(profile));
        }
    }

    private static Template buildPbTemplate(String boss, String time, int count) {
        return Template.builder()
            .template(String.format("%s has defeated {{boss}} with a new personal best time of %s and a completion count of %d", PLAYER_NAME, time, count))
            .replacement("{{boss}}", Replacements.ofWiki(boss))
            .build();
    }
}

