    @Test
    void testNotifyTwoProfilesFromOneAnalyzedDrop() {
        PigeonProfile clan = lootProfile(
            "Clan", true, 500, "", "Clan: %LOOT%", "https://example.com/clan");
        PigeonProfile friends = lootProfile(
            "Friends", true, 1_000, "Ruby", "Friends: %LOOT%", "https://example.com/friends");
        PigeonProfile disabled = lootProfile(
            "Disabled", false, 1, "", "Disabled", "https://example.com/disabled");
        mockStoredProfiles(clan, friends, disabled);

        NPC npc = mock(NPC.class);
        when(npc.getName()).thenReturn("Rasmus");
        when(npc.getId()).thenReturn(9999);
        mockWorldNpcs(npc);
        plugin.onNpcLootReceived(new NpcLootReceived(
            npc, Collections.singletonList(new ItemStack(ItemID.RUBY, 1))));

        ArgumentCaptor<PigeonConfig> configs = ArgumentCaptor.forClass(PigeonConfig.class);
        ArgumentCaptor<String> urls = ArgumentCaptor.forClass(String.class);
        ArgumentCaptor<NotificationBody> bodies = ArgumentCaptor.forClass(NotificationBody.class);
        verify(messageHandler, times(2)).createMessage(
            configs.capture(), urls.capture(), anyBoolean(), bodies.capture());

        org.junit.jupiter.api.Assertions.assertEquals(
            List.of("https://example.com/clan", "https://example.com/friends"), urls.getAllValues());
        org.junit.jupiter.api.Assertions.assertEquals(
            "Clan: 1 x Ruby (900)", bodies.getAllValues().get(0).getText().evaluate(false));
        org.junit.jupiter.api.Assertions.assertEquals(
            "Friends: 1 x Ruby (900)", bodies.getAllValues().get(1).getText().evaluate(false));
        LootNotificationData clanData = (LootNotificationData) bodies.getAllValues().get(0).getExtra();
        LootNotificationData friendsData = (LootNotificationData) bodies.getAllValues().get(1).getExtra();
        org.junit.jupiter.api.Assertions.assertEquals(
            EnumSet.of(LootCriteria.VALUE), ((AnnotatedItemStack) clanData.getItems().iterator().next()).getCriteria());
        org.junit.jupiter.api.Assertions.assertEquals(
            EnumSet.of(LootCriteria.ALLOWLIST), ((AnnotatedItemStack) friendsData.getItems().iterator().next()).getCriteria());
    }

