package pigeon.profiles;

import com.google.gson.Gson;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

class ProfileServiceTest {
    private InMemoryProfileRepository repository;
    private ProfileRuntimeService runtimeService;
    private ProfileService service;

    @BeforeEach
    void setUp() {
        repository = new InMemoryProfileRepository();
        runtimeService = mock(ProfileRuntimeService.class);
        service = new ProfileService(repository, new ProfileCodec(new Gson()), runtimeService);
    }

    @Test
    void createsClonesAndEnablesProfilesIndependently() {
        PigeonProfile original = service.create("Clan");
        PigeonProfile clone = service.cloneProfile(original.getId(), "Friends");

        assertNotEquals(original.getId(), clone.getId());
        assertEquals(
            List.of("Clan", "Friends"),
            service.list().stream().map(PigeonProfile::getName).collect(Collectors.toList())
        );

        service.setEnabled(original.getId(), false);
        assertFalse(repository.findById(original.getId()).orElseThrow().isEnabled());
        assertTrue(repository.findById(clone.getId()).orElseThrow().isEnabled());
    }

    @Test
    void importsAsNewProfileWithoutReusingSharedId() {
        PigeonProfile source = service.create("Shared");
        String export = service.exportProfile(source.getId(), false);

        PigeonProfile imported = service.importAsNew(export);

        assertNotEquals(source.getId(), imported.getId());
        assertEquals(source.getName(), imported.getName());
        assertFalse(imported.isEnabled());
    }

    @Test
    void deletesOnlyRequestedProfile() {
        PigeonProfile first = service.create("First");
        PigeonProfile second = service.create("Second");

        assertTrue(service.delete(first.getId()));
        assertFalse(service.delete(first.getId()));
        assertEquals(List.of(second), service.list());
    }

    @Test
    void updatesExistingProfileConfiguration() {
        PigeonProfile original = service.create("Clan");
        PigeonProfile updated = original.toBuilder()
            .webhooks(new ProfileWebhooks(List.of("https://example.com/clan"), Map.of()))
            .build();

        service.update(updated);

        assertEquals(updated, repository.findById(original.getId()).orElseThrow());
    }

    @Test
    void invalidatesRuntimeCacheAfterSuccessfulMutations() {
        PigeonProfile profile = service.create("Clan");
        verify(runtimeService).invalidate();

        clearInvocations(runtimeService);
        service.setEnabled(profile.getId(), false);
        verify(runtimeService).invalidate();

        clearInvocations(runtimeService);
        assertTrue(service.delete(profile.getId()));
        verify(runtimeService).invalidate();

        clearInvocations(runtimeService);
        assertFalse(service.delete(profile.getId()));
        verifyNoInteractions(runtimeService);
    }

    @Test
    void reportsOverlappingEnabledRoutesWithoutExposingWebhookSecrets() {
        String shared = "https://discord.com/api/webhooks/123/super-secret-token";
        PigeonProfile clan = service.create("Clan");
        service.update(clan.toBuilder()
            .webhooks(new ProfileWebhooks(List.of(shared), Map.of()))
            .build());
        PigeonProfile friends = service.create("Friends");
        service.update(friends.toBuilder()
            .webhooks(new ProfileWebhooks(List.of(), Map.of("lootWebhook", List.of(shared))))
            .build());
        PigeonProfile disabled = service.create("Disabled");
        service.update(disabled.toBuilder()
            .webhooks(new ProfileWebhooks(List.of(shared), Map.of()))
            .enabled(false)
            .build());

        List<ProfileRouteOverlap> overlaps = service.findOverlappingRoutes();

        assertEquals(1, overlaps.size());
        assertEquals("https://discord.com", overlaps.get(0).getEndpoint());
        assertEquals(List.of("Clan", "Friends"), overlaps.get(0).getProfileNames());
        assertFalse(overlaps.get(0).toString().contains("super-secret-token"));
    }

    private static class InMemoryProfileRepository implements ProfileRepository {
        private final Map<UUID, PigeonProfile> profiles = new LinkedHashMap<>();

        @Override
        public List<PigeonProfile> findAll() {
            return new ArrayList<>(profiles.values());
        }

        @Override
        public Optional<PigeonProfile> findById(UUID id) {
            return Optional.ofNullable(profiles.get(id));
        }

        @Override
        public void save(PigeonProfile profile) {
            profiles.put(profile.getId(), profile);
        }

        @Override
        public boolean delete(UUID id) {
            return profiles.remove(id) != null;
        }
    }
}

package pigeon.profiles;

import com.google.gson.Gson;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class ConfigProfileRepositoryTest {
    private final Map<String, String> storedConfig = new HashMap<>();
    private Gson gson;
    private ProfileCodec codec;
    private ConfigProfileRepository repository;

    @BeforeEach
    void setUp() {
        gson = new Gson();
        ConfigManager configManager = mock(ConfigManager.class);

        when(configManager.getConfiguration(anyString(), anyString()))
            .thenAnswer(invocation -> storedConfig.get(key(invocation.getArgument(0), invocation.getArgument(1))));
        doAnswer(invocation -> {
            Object value = invocation.getArgument(2);
            storedConfig.put(
                key(invocation.getArgument(0), invocation.getArgument(1)),
                String.valueOf(value)
            );
            return null;
        }).when(configManager).setConfiguration(anyString(), anyString(), any());
        doAnswer(invocation -> {
            storedConfig.remove(key(invocation.getArgument(0), invocation.getArgument(1)));
            return null;
        }).when(configManager).unsetConfiguration(anyString(), anyString());

        codec = spy(new ProfileCodec(gson));
        repository = new ConfigProfileRepository(configManager, gson, codec);
    }

    @Test
    void freshRepositoryStartsWithoutProfiles() {
        assertEquals(List.of(), repository.findAll());
    }

    @Test
    void reusesDecodedProfilesUntilStoredJsonChanges() {
        PigeonProfile profile = PigeonProfile.create("Clan");
        String profileJson = codec.toJson(profile, true);
        storedConfig.put(
            key(ConfigProfileRepository.CONFIG_GROUP, ConfigProfileRepository.INDEX_KEY),
            gson.toJson(List.of(profile.getId()))
        );
        storedConfig.put(
            key(ConfigProfileRepository.CONFIG_GROUP, "profile_" + profile.getId()),
            profileJson
        );
        clearInvocations(codec);

        PigeonProfile first = repository.findAll().get(0);
        PigeonProfile second = repository.findAll().get(0);

        assertSame(first, second);
        verify(codec, times(1)).fromJson(profileJson);

        PigeonProfile disabled = profile.toBuilder().enabled(false).build();
        String updatedJson = codec.toJson(disabled, true);
        storedConfig.put(
            key(ConfigProfileRepository.CONFIG_GROUP, "profile_" + profile.getId()),
            updatedJson
        );

        assertFalse(repository.findAll().get(0).isEnabled());
        verify(codec, times(1)).fromJson(updatedJson);
    }

    @Test
    void savesLoadsAndDeletesInIndexOrder() {
        PigeonProfile clan = PigeonProfile.create("Clan");
        PigeonProfile friends = PigeonProfile.create("Friends");

        repository.save(clan);
        repository.save(friends);
        repository.save(clan.toBuilder().enabled(false).build());

        assertEquals(
            List.of("Clan", "Friends"),
            repository.findAll().stream().map(PigeonProfile::getName).collect(java.util.stream.Collectors.toList())
        );
        assertFalse(repository.findById(clan.getId()).orElseThrow().isEnabled());

        repository.delete(clan.getId());
        assertEquals(List.of(friends), repository.findAll());
        assertFalse(repository.findById(clan.getId()).isPresent());
    }

    @Test
    void rejectsMalformedStoredIndex() {
        storedConfig.put(key(ConfigProfileRepository.CONFIG_GROUP, ConfigProfileRepository.INDEX_KEY), "not-json");

        assertThrows(ProfileValidationException.class, repository::findAll);
    }

    private static String key(String group, String item) {
        return group + "." + item;
    }
}

