@Slf4j
public class CollectionNotifier extends BaseNotifier {
    static final Pattern COLLECTION_LOG_REGEX = Pattern.compile("New item added to your collection log: (?<itemName>(.*))");
    public static final String ADDITION_WARNING = "Collection notifier will not fire unless you enable the game setting: Collection log - New addition notification";
    public static final int POPUP_PREFIX_LENGTH = "New item:".length();

    static final @VisibleForTesting int TOTAL_ENTRIES = 1_692; // fallback if COLLECTION_COUNT_MAX is not populated
    private static final Duration RECENT_DROP = Duration.ofSeconds(30L);

    /**
     * Red-black tree of ranks by log thresholds; populated using client cache in {@link #init()}.
     *
     * @see <a href="https://oldschool.runescape.wiki/w/Collection_log#Ranks">Wiki Reference</a>
     */
    private final NavigableMap<Integer, CollectionLogRank> rankByThreshold = new TreeMap<>();

    /**
     * The number of completed entries in the collection log, as implied by {@link VarPlayerID#COLLECTION_COUNT}.
     */
    private final AtomicInteger completed = new AtomicInteger(-1);

    private final AtomicBoolean popupStarted = new AtomicBoolean(false);

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ItemSearcher itemSearcher;

    @Inject
    private KillCountService killCountService;

    @Inject
    private RarityService rarityService;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    private boolean initialized = false;

    @Override
    public boolean isEnabled() {
        return config.notifyCollectionLog() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.collectionWebhook();
    }

    public void reset() {
        // note: unlike other notifiers, we do not need to reset completed after each message
        // in fact, resetting would be problematic for an edge case with multiple completions in a single tick
        this.completed.set(-1);
        this.popupStarted.set(false);
    }

    public void onGameState(GameState newState) {
        if (newState != GameState.HOPPING && newState != GameState.LOGGED_IN)
            this.reset();
    }

    public void onTick() {
        if (!initialized) {
            clientThread.invokeLater(this::init);
        }

        if (client.getGameState() != GameState.LOGGED_IN) {
            // this shouldn't ever happen, but just in case
            completed.set(-1);
        } else if (completed.get() < 0) {
            // initialize collection log entry completion count
            int varpValue = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
            if (varpValue > 0)
                completed.set(varpValue);
        }
    }

    public void onVarPlayer(VarbitChanged event) {
        if (event.getVarpId() != VarPlayerID.COLLECTION_COUNT)
            return;

        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean active = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : config.notifyCollectionLog();
        // Keep `completed` updated when no notifier path will increment it.
        if (!active) {
            completed.set(event.getValue());
        }
    }

    public void onChatMessage(String chatMessage) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (!enabled || client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 1) {
            // require notifier enabled without popup mode to use chat event
            return;
        }

        Matcher collectionMatcher = COLLECTION_LOG_REGEX.matcher(chatMessage);
        if (collectionMatcher.find()) {
            String item = collectionMatcher.group("itemName");
            clientThread.invokeLater(() -> {
                if (profiles.isProfilesConfigured()) handleProfileNotify(item, profiles);
                else handleNotify(item);
            });
        }
    }

    public void onScript(int scriptId) {
        if (scriptId == ScriptID.NOTIFICATION_START) {
            popupStarted.set(true);
        } else if (scriptId == ScriptID.NOTIFICATION_DELAY) {
            String topText = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
            ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
            boolean enabled = profiles.isProfilesConfigured()
                ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
                : isEnabled();
            if (popupStarted.getAndSet(false) && "Collection log".equalsIgnoreCase(topText) && enabled) {
                String bottomText = Utils.sanitize(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN));
                String item = bottomText.substring(POPUP_PREFIX_LENGTH).trim();
                if (profiles.isProfilesConfigured()) handleProfileNotify(item, profiles);
                else handleNotify(item);
            }
        }
    }

    private void init() {
        final int maxCount = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
        if (maxCount <= 0) {
            // underlying data not yet initialized; retry later
            return;
        }

        populateThresholds(maxCount);
        initialized = true;
    }

    private void populateThresholds(int maxCount) {
        for (CollectionLogRank rank : CollectionLogRank.values()) {
            try {
                rankByThreshold.put(rank.getClogRankThreshold(client, maxCount), rank);
            } catch (Exception e) {
                String msg = "Could not find struct for {}";
                if (log.isDebugEnabled()) {
                    log.debug(msg, rank, e);
                } else {
                    log.warn(msg, rank);
                }
            }
        }
        log.debug("Rank Thresholds: {}", rankByThreshold);
    }

    private void handleNotify(String itemName) {
        if (!initialized) {
            // initialize rankByThreshold based on the fallback total entry count
            populateThresholds(TOTAL_ENTRIES);
        }

        // check denylist
        boolean denylisted = ConfigUtil.readDelimited(config.collectionDenylist())
            .map(Utils::regexify)
            .filter(Objects::nonNull)
            .map(pattern -> pattern.matcher(itemName))
            .anyMatch(Matcher::find);
        if (denylisted) {
            log.debug("Skipping clog notif due to denylist: {}", itemName);
            return;
        }

        // varp isn't updated for a few ticks, so we increment the count locally.
        // this approach also has the benefit of yielding incrementing values even when
        // multiple collection log entries are completed within a single tick.
        int completed = this.completed.updateAndGet(i -> i >= 0 ? i + 1 : i);
        int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX); // unique; doesn't over-count duplicates
        boolean varpValid = total > 0 && completed > 0;
        var nextRankEntry = rankByThreshold.higherEntry(completed);
        var prevRankEntry = rankByThreshold.floorEntry(completed);
        CollectionLogRank rank = prevRankEntry != null ? prevRankEntry.getValue() : null;
        CollectionLogRank nextRank = completed > 0 && nextRankEntry != null ? nextRankEntry.getValue() : null;
        Integer rankProgress = prevRankEntry != null ? completed - prevRankEntry.getKey() : null;
        var justCompletedEntry = prevRankEntry != null && rankProgress == 0 ? rankByThreshold.lowerEntry(prevRankEntry.getKey()) : null;
        CollectionLogRank justCompletedRank = justCompletedEntry != null ? justCompletedEntry.getValue() : null;
        Integer logsNeededForNextRank = (completed > 0 && nextRankEntry != null) ? nextRankEntry.getKey() - completed : null;
        if (!varpValid) {
            // This occurs if the player doesn't have the character summary tab selected
            log.debug("Collection log progress varps were invalid ({} / {})", completed, total);
        }

        // build message
        Template notifyMessage = Template.builder()
            .template(config.collectionNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
            .replacement("%ITEM%", Replacements.ofWiki(itemName))
            .replacement("%COMPLETED%", Replacements.ofText(completed > 0 ? String.valueOf(completed) : "?"))
            .replacement("%TOTAL_POSSIBLE%", Replacements.ofText(String.valueOf(total > 0 ? total : TOTAL_ENTRIES)))
            .replacement("%RANK%", Replacements.ofText(rank != null ? rank.toString() : "Unknown"))
            .build();

        // populate metadata
        Integer itemId = itemSearcher.findItemId(itemName);
        Long price = itemId != null ? ItemUtils.getPrice(itemManager, itemId) : null;
        Drop loot = itemId != null ? getLootSource(itemId) : null;
        Integer killCount = loot != null ? killCountService.getKillCount(loot.getCategory(), loot.getSource()) : null;
        OptionalDouble rarity = loot != null && loot.getCategory() == LootRecordType.NPC ?
            rarityService.getRarity(loot.getSource(), itemId, 1) : OptionalDouble.empty();
        CollectionNotificationData extra = new CollectionNotificationData(
            itemName,
            itemId,
            price,
            varpValid ? completed : null,
            varpValid ? total : null,
            rank,
            rankProgress,
            logsNeededForNextRank,
            nextRank,
            justCompletedRank,
            loot != null ? loot.getSource() : null,
            loot != null ? loot.getCategory() : null,
            killCount,
            rarity.isPresent() ? rarity.getAsDouble() : null
        );

        createMessage(config.collectionSendImage(), NotificationBody.builder()
            .text(notifyMessage)
            .thumbnailUrl(itemId != null ? ItemUtils.getItemImageUrl(itemId) : null)
            .extra(extra)
            .type(NotificationType.COLLECTION)
            .build());
    }

    private void handleProfileNotify(String itemName, ProfileRuntimeSnapshot profiles) {
        List<PigeonProfileConfig> candidates = profiles.getEnabledProfiles().stream()
            .filter(this::isProfileEnabled)
            .collect(java.util.stream.Collectors.toList());
        if (candidates.isEmpty()) return;
        if (!initialized) populateThresholds(TOTAL_ENTRIES);

        // Advance shared collection state exactly once for this detected addition.
        int completed = this.completed.updateAndGet(i -> i >= 0 ? i + 1 : i);
        int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
        boolean varpValid = total > 0 && completed > 0;
        var nextRankEntry = rankByThreshold.higherEntry(completed);
        var prevRankEntry = rankByThreshold.floorEntry(completed);
        CollectionLogRank rank = prevRankEntry != null ? prevRankEntry.getValue() : null;
        CollectionLogRank nextRank = completed > 0 && nextRankEntry != null ? nextRankEntry.getValue() : null;
        Integer rankProgress = prevRankEntry != null ? completed - prevRankEntry.getKey() : null;
        var justCompletedEntry = prevRankEntry != null && rankProgress == 0
            ? rankByThreshold.lowerEntry(prevRankEntry.getKey()) : null;
        CollectionLogRank justCompletedRank = justCompletedEntry != null ? justCompletedEntry.getValue() : null;
        Integer logsNeededForNextRank = completed > 0 && nextRankEntry != null
            ? nextRankEntry.getKey() - completed : null;

        Integer itemId = itemSearcher.findItemId(itemName);
        Long price = itemId != null ? ItemUtils.getPrice(itemManager, itemId) : null;
        Drop loot = itemId != null ? getLootSource(itemId) : null;
        Integer killCount = loot != null ? killCountService.getKillCount(loot.getCategory(), loot.getSource()) : null;
        OptionalDouble rarity = loot != null && loot.getCategory() == LootRecordType.NPC
            ? rarityService.getRarity(loot.getSource(), itemId, 1) : OptionalDouble.empty();
        CollectionNotificationData extra = new CollectionNotificationData(
            itemName, itemId, price, varpValid ? completed : null, varpValid ? total : null,
            rank, rankProgress, logsNeededForNextRank, nextRank, justCompletedRank,
            loot != null ? loot.getSource() : null, loot != null ? loot.getCategory() : null,
            killCount, rarity.isPresent() ? rarity.getAsDouble() : null);

        NotificationBody<?> outbound = null;
        for (PigeonProfileConfig profile : candidates) {
            boolean denylisted = ConfigUtil.readDelimited(profile.collectionDenylist())
                .map(Utils::regexify)
                .filter(Objects::nonNull)
                .map(pattern -> pattern.matcher(itemName))
                .anyMatch(Matcher::find);
            if (denylisted) continue;

            Template notifyMessage = Template.builder()
                .template(profile.collectionNotifyMessage())
                .replacementBoundary("%")
                .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
                .replacement("%ITEM%", Replacements.ofWiki(itemName))
                .replacement("%COMPLETED%", Replacements.ofText(completed > 0 ? String.valueOf(completed) : "?"))
                .replacement("%TOTAL_POSSIBLE%", Replacements.ofText(String.valueOf(total > 0 ? total : TOTAL_ENTRIES)))
                .replacement("%RANK%", Replacements.ofText(rank != null ? rank.toString() : "Unknown"))
                .build();
            NotificationBody<?> body = NotificationBody.builder()
                .text(notifyMessage)
                .thumbnailUrl(itemId != null ? ItemUtils.getItemImageUrl(itemId) : null)
                .extra(extra)
                .type(NotificationType.COLLECTION)
                .build();
            if (deliver(profile, profile.collectionWebhook(), profile.collectionSendImage(), body)
                && outbound == null) outbound = body;
        }
        if (outbound != null) publishPluginMessage(outbound);
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyCollectionLog() && profileEligibilityService.isEligible(profile);
    }

    @Nullable
    private Drop getLootSource(int itemId) {
        Drop drop = killCountService.getLastDrop();
        if (drop == null) return null;
        if (Duration.between(drop.getTime(), Instant.now()).compareTo(RECENT_DROP) > 0) return null;
        for (ItemStack item : drop.getItems()) {
            if (item.getId() == itemId) {
                return drop;
            }
        }
        return null;
    }

}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.util.QuestUtils;
import pigeon.util.Utils;
import pigeon.notifiers.data.QuestNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;

public class QuestNotifier extends BaseNotifier {

    @Inject
    private ClientThread clientThread;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        return config.notifyQuest() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.questWebhook();
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.QUESTSCROLL) {
            ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
            boolean enabled = profiles.isProfilesConfigured()
                ? profiles.getEnabledProfiles().stream()
                    .anyMatch(profile -> profile.notifyQuest() && profileEligibilityService.isEligible(profile))
                : isEnabled();
            if (!enabled) {
                return;
            }

            Widget quest = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE);
            if (quest != null) {
                String questText = quest.getText();
                // 1 tick delay to ensure relevant varbits have been processed by the client
                clientThread.invokeLater(() -> handleNotify(questText, profiles));
            }
        }
    }

    private void handleNotify(String questText, ProfileRuntimeSnapshot profiles) {
        int completedQuests = client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT);
        int totalQuests = client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT);
        boolean validQuests = completedQuests > 0 && totalQuests > 0;

        int questPoints = client.getVarpValue(VarPlayerID.QP);
        int totalQuestPoints = client.getVarbitValue(VarbitID.QP_MAX);
        boolean validPoints = questPoints > 0 && totalQuestPoints > 0;

        String parsed = QuestUtils.parseQuestWidget(questText);
        if (parsed == null) return;

        QuestNotificationData extra = new QuestNotificationData(
            parsed,
            validQuests ? completedQuests : null,
            validQuests ? totalQuests : null,
            validPoints ? questPoints : null,
            validPoints ? totalQuestPoints : null
        );

        if (!profiles.isProfilesConfigured()) {
            NotificationBody<?> body = createBody(config, parsed, extra);
            createMessage(config.questSendImage(), body);
            return;
        }

        NotificationBody<?> outboundBody = null;
        for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
            if (!profile.notifyQuest() || !profileEligibilityService.isEligible(profile)) {
                continue;
            }

            NotificationBody<?> body = createBody(profile, parsed, extra);
            deliver(profile, profile.questWebhook(), profile.questSendImage(), body);
            if (outboundBody == null) {
                outboundBody = body;
            }
        }
        if (outboundBody != null) {
            publishPluginMessage(outboundBody);
        }
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, String parsed,
                                            QuestNotificationData extra) {
        Template notifyMessage = Template.builder()
            .template(deliveryConfig.questNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
            .replacement("%QUEST%", Replacements.ofWiki(parsed))
            .build();

        return NotificationBody.builder()
            .text(notifyMessage)
            .extra(extra)
            .type(NotificationType.QUEST)
            .build();
    }
}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.notifiers.data.BossNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import pigeon.util.KillCountService;
import pigeon.util.TimeUtils;
import pigeon.util.Utils;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Duration;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.apache.commons.lang3.ObjectUtils.defaultIfNull;

@Slf4j
@Singleton
public class KillCountNotifier extends BaseNotifier {

    public static final String SPAM_WARNING = "Kill Count Notifier requires disabling the in-game setting: Filter out boss kill-count with spam-filter";

    private static final Pattern PRIMARY_REGEX = Pattern.compile("Your (?<key>.+)\\s(?<type>kill|chest|completion|harvest|success|opened)\\s?count is: ?(?<value>[\\d,]+)\\b", Pattern.CASE_INSENSITIVE);
    private static final Pattern SECONDARY_REGEX = Pattern.compile("Your (?:completed|subdued) (?<key>.+) count is: (?<value>[\\d,]+)\\b");
    private static final Pattern TIME_REGEX = Pattern.compile("(?:Duration|time|Subdued in):? (?<time>[\\d:]+(?:.\\d+)?)\\.?(?: Personal best: (?<pbtime>[\\d:+]+(?:.\\d+)?))?", Pattern.CASE_INSENSITIVE);

    private static final String BA_BOSS_NAME = "Penance Queen";

    /**
     * The maximum number of ticks to hold onto a fight duration without a corresponding boss name.
     * <p>
     * Note: unlike other notifiers, this is applied asymmetrically
     * (i.e., we do not wait for fight duration if only boss name was received on the tick)
     */
    @VisibleForTesting
    static final int MAX_BAD_TICKS = 10;

    @Inject
    private KillCountService kcService;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    private final AtomicInteger badTicks = new AtomicInteger();
    private final AtomicReference<BossNotificationData> data = new AtomicReference<>();
    private ProfileRuntimeSnapshot pendingProfileSnapshot;

    @Override
    public boolean isEnabled() {
        return config.notifyKillCount() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.killCountWebhook();
    }

    public void reset() {
        this.data.set(null);
        this.badTicks.set(0);
        this.pendingProfileSnapshot = null;
    }

    public void onGameMessage(String message) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (enabled) {
            parse(client, message).ifPresent(parsed -> {
                if (pendingProfileSnapshot == null && profiles.isProfilesConfigured()) {
                    pendingProfileSnapshot = profiles;
                }
                updateData(parsed);
            });
        }
    }

    public void onFriendsChatNotification(String message) {
        // For CoX, Jagex sends duration via FRIENDSCHATNOTIFICATION
        if (message.startsWith("Congratulations - your raid is complete!"))
            this.onGameMessage(message);
    }

    public void onWidget(WidgetLoaded event) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(profile ->
                isProfileEnabled(profile) && profile.killCountPenanceQueen())
            : isEnabled();
        if (!enabled)
            return;

        // Barbarian Assault: Track Penance Queen kills
        boolean queenEnabled = profiles.isProfilesConfigured() || config.killCountPenanceQueen();
        if (queenEnabled && event.getGroupId() == InterfaceID.BARBASSAULT_WAVECOMPLETE) {
            Widget widget = client.getWidget(InterfaceID.BarbassaultWavecomplete.BARBASSAULT_COMPL_QUEENREWARDS);
            // https://oldschool.runescape.wiki/w/Barbarian_Assault/Rewards#Earning_Honour_points
            if (widget != null && widget.getText().contains("80 ") && widget.getText().contains("5 ")) {
                int gambleCount = client.getVarbitValue(VarbitID.BARBASSAULT_GAMBLECOUNT);
                this.data.set(new BossNotificationData(BA_BOSS_NAME, gambleCount, "The Queen is dead!", null, null, null, null));
                if (profiles.isProfilesConfigured()) pendingProfileSnapshot = profiles;
            }
        }
    }

    public void onTick() {
        BossNotificationData data = this.data.get();
        if (data != null) {
            if (data.getBoss() != null && data.getCount() != null) {
                if (pendingProfileSnapshot != null && pendingProfileSnapshot.isProfilesConfigured()) {
                    handleProfileKill(data, pendingProfileSnapshot);
                // ensure legacy notifier was not disabled during bad ticks wait period
                } else if (isEnabled()) {
                    // once boss name has arrived, we notify at tick end (even if duration hasn't arrived)
                    handleKill(data);
                }
                reset();
            } else if (badTicks.incrementAndGet() > MAX_BAD_TICKS) {
                // after receiving fight duration, allow up to 10 ticks for boss name to arrive.
                // if boss name doesn't arrive in time, reset (to avoid stale data contaminating later notifications)
                reset();
            }
        }
    }

    private void handleKill(BossNotificationData data) {
        // ensure data is present
        if (data.getBoss() == null || data.getCount() == null)
            return;

        // ensure interval met or pb or ba, depending on config
        boolean isPb = data.isPersonalBest() == Boolean.TRUE;
        boolean ba = data.getBoss().equals(BA_BOSS_NAME);
        if (!checkKillInterval(config, data.getCount(), isPb) && !ba)
            return;

        // populate personalBest if absent
        if (data.getPersonalBest() == null && !isPb) {
            Duration pb = kcService.getPb(data.getBoss());
            if (pb != null && (data.getTime() == null || pb.compareTo(data.getTime()) < 0)) {
                data = data.withPersonalBest(pb);
            }
        }

        createMessage(config.killCountSendImage(), createBody(config, data, isPb, ba));
    }

    private void handleProfileKill(BossNotificationData data, ProfileRuntimeSnapshot profiles) {
        if (data.getBoss() == null || data.getCount() == null) return;
        boolean isPb = data.isPersonalBest() == Boolean.TRUE;
        boolean ba = data.getBoss().equals(BA_BOSS_NAME);

        BossNotificationData enriched = populatePersonalBest(data, isPb);
        NotificationBody<?> outbound = null;
        for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
            if (!isProfileEnabled(profile) || (ba && !profile.killCountPenanceQueen())
                || (!ba && !checkKillInterval(profile, data.getCount(), isPb))) {
                continue;
            }
            NotificationBody<?> body = createBody(profile, enriched, isPb, ba);
            if (deliver(profile, profile.killCountWebhook(), profile.killCountSendImage(), body)
                && outbound == null) {
                outbound = body;
            }
        }
        if (outbound != null) publishPluginMessage(outbound);
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyKillCount() && profileEligibilityService.isEligible(profile);
    }

    private BossNotificationData populatePersonalBest(BossNotificationData data, boolean isPb) {
        if (data.getPersonalBest() == null && !isPb) {
            Duration pb = kcService.getPb(data.getBoss());
            if (pb != null && (data.getTime() == null || pb.compareTo(data.getTime()) < 0)) {
                return data.withPersonalBest(pb);
            }
        }
        return data;
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, BossNotificationData data,
                                            boolean isPb, boolean ba) {
        String player = Utils.getPlayerName(client);
        String time = TimeUtils.format(data.getTime(), TimeUtils.isPreciseTiming(client));
        Template content = Template.builder()
            .template(isPb ? deliveryConfig.killCountBestTimeMessage() : deliveryConfig.killCountMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(player))
            .replacement("%BOSS%", Replacements.ofWiki(data.getBoss()))
            .replacement("%COUNT%", Replacements.ofText(data.getCount() + (ba ? " high gambles" : "")))
            .replacement("%TIME%", Replacements.ofText(time))
            .build();
        return NotificationBody.builder()
            .text(content)
            .extra(data)
            .playerName(player)
            .type(NotificationType.KILL_COUNT)
            .build();
    }

    private boolean checkKillInterval(PigeonConfig deliveryConfig, int killCount, boolean pb) {
        if (pb && deliveryConfig.killCountNotifyBestTime())
            return true;

        if (killCount == 1 && deliveryConfig.killCountNotifyInitial())
            return true;

        int interval = deliveryConfig.killCountInterval();
        return interval <= 1 || killCount % interval == 0;
    }

    private void updateData(BossNotificationData updated) {
        data.getAndUpdate(old -> {
            if (old == null) {
                return updated;
            } else {
                // Boss data and timing are sent in separate messages
                // where the order of the messages differs depending on the boss.
                // Here, we update data without setting any not-null values back to null.
                String boss = defaultIfNull(updated.getBoss(), old.getBoss());
                boolean tob = boss != null && boss.startsWith("Theatre of Blood"); // prefer challenge time message that comes first: https://github.com/pajlads/DinkPlugin/issues/585
                return new BossNotificationData(
                    boss,
                    defaultIfNull(updated.getCount(), old.getCount()),
                    defaultIfNull(updated.getGameMessage(), old.getGameMessage()),
                    updated.getTime() == null || (tob && old.getTime() != null) ? old.getTime() : updated.getTime(),
                    updated.isPersonalBest() == null || (tob && old.isPersonalBest() != null) ? old.isPersonalBest() : updated.isPersonalBest(),
                    updated.getPersonalBest() == null || (tob && old.getPersonalBest() != null) ? old.getPersonalBest() : updated.getPersonalBest(),
                    defaultIfNull(updated.getParty(), old.getParty())
                );
            }
        });
    }

    private static Optional<BossNotificationData> parse(Client client, String message) {
        if (message.startsWith("Preparation")) return Optional.empty();
        Optional<Pair<String, Integer>> boss = parseBoss(message);
        if (boss.isPresent())
            return boss.map(pair -> new BossNotificationData(pair.getLeft(), pair.getRight(), message, null, null, null, Utils.getBossParty(client, pair.getLeft())));

        // TOB reports final wave duration before challenge time in the same message; skip to the part we care about
        int tobIndex = message.startsWith("Wave") ? message.indexOf(KillCountService.TOB) : -1;
        String msg = tobIndex < 0 ? message : message.substring(tobIndex);

        return parseTime(msg).map(t -> new BossNotificationData(tobIndex < 0 ? null : KillCountService.TOB, null, null, t.getTime(), t.isPb(), t.getPb(), null));
    }

    private static Optional<ParsedTime> parseTime(String message) {
        Matcher matcher = TIME_REGEX.matcher(message);
        if (matcher.find()) {
            Duration duration = TimeUtils.parseTime(matcher.group("time"));
            boolean isPb = message.toLowerCase().contains("(new personal best)");
            String pbTime = matcher.group("pbtime");
            Duration pb = pbTime != null ? TimeUtils.parseTime(pbTime) : null;
            return Optional.of(new ParsedTime(duration, isPb, pb));
        }
        return Optional.empty();
    }

    public static Optional<Pair<String, Integer>> parseBoss(String message) {
        Matcher primary = PRIMARY_REGEX.matcher(message);
        Matcher secondary; // lazy init
        if (primary.find()) {
            String boss = parsePrimaryBoss(primary.group("key"), primary.group("type"));
            String count = primary.group("value");
            return result(boss, count);
        } else if ((secondary = SECONDARY_REGEX.matcher(message)).find()) {
            String key = parseSecondary(secondary.group("key"));
            String value = secondary.group("value");
            return result(key, value);
        }
        return Optional.empty();
    }

    private static Optional<Pair<String, Integer>> result(String boss, String count) {
        // safely transform (String, String) => (String, Int)
        try {
            return Optional.ofNullable(boss).map(k -> Pair.of(boss, Integer.parseInt(count.replace(",", ""))));
        } catch (NumberFormatException e) {
            log.debug("Failed to parse kill count [{}] for boss [{}]", count, boss);
            return Optional.empty();
        }
    }

    @Nullable
    private static String parsePrimaryBoss(String boss, String type) {
        switch (type.toLowerCase()) {
            case "chest":
                if ("Barrows".equalsIgnoreCase(boss))
                    return boss;
                if ("Lunar".equals(boss))
                    return boss + " " + type;
                return null;

            case "completion":
                if (KillCountService.GAUNTLET_NAME.equalsIgnoreCase(boss))
                    return KillCountService.GAUNTLET_BOSS;
                if (KillCountService.CG_NAME.equalsIgnoreCase(boss))
                    return KillCountService.CG_BOSS;
                return null;

            case "harvest":
                if (KillCountService.HERBIBOAR.equalsIgnoreCase(boss))
                    return KillCountService.HERBIBOAR;

            case "kill":
            case "success":
            case "opened":
                return boss;

            default:
                return null;
        }
    }

    private static String parseSecondary(String boss) {
        if (boss == null || "Wintertodt".equalsIgnoreCase(boss))
            return boss;

        int modeSeparator = boss.lastIndexOf(':');
        String raid = modeSeparator > 0 ? boss.substring(0, modeSeparator) : boss;
        if (raid.equalsIgnoreCase(KillCountService.TOB)
            || raid.equalsIgnoreCase(KillCountService.TOA)
            || raid.equalsIgnoreCase(KillCountService.COX)
            || raid.equalsIgnoreCase(KillCountService.COX + " Challenge Mode"))
            return boss;

        return null;
    }

    @Value
    private static class ParsedTime {
        Duration time;
        boolean isPb;
        @Nullable Duration pb;
    }
}

package pigeon.notifiers;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import pigeon.domain.AchievementDiary;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
