import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

@Slf4j
@Singleton
public class MetaNotifier extends BaseNotifier {
    static final @VisibleForTesting String RL_CHAT_CMD_PLUGIN_NAME = ChatCommandsPlugin.class.getSimpleName().toLowerCase();
    static final @VisibleForTesting int INIT_TICKS = 10; // 6 seconds after login
    private static final int SARCOPHAGUS_WALL_ID = ObjectID.TOA_VAULT_BARRIER_PARENT;
    private boolean isToaPurple = false;

    private static final int[] TOA_CHEST_VARBS;

    private final AtomicInteger loginTicks = new AtomicInteger(-1);

    private String cachedPlayerName;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private Gson gson;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        return StringUtils.isNotBlank(config.metadataWebhook()) && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.metadataWebhook();
    }

    public void onGameState(GameState oldState, GameState newState) {
        // inspect oldState because we don't want a notification on each world hop
        if (oldState == GameState.LOGGING_IN && newState == GameState.LOGGED_IN) {
            loginTicks.set(INIT_TICKS);
        }
        // check if the oldState is any that can be considered "in game", and if the new state is "LOGIN_SCREEN"
        if ((oldState == GameState.LOGGED_IN || oldState == GameState.CONNECTION_LOST || oldState == GameState.HOPPING)
            && newState == GameState.LOGIN_SCREEN && hasEnabledDelivery()) {
            notifyLogout(profileRuntimeService.snapshot());
        }
    }

    public void onWallObjectSpawned(WallObjectSpawned event) {
        final WallObject wallObject = event.getWallObject();

        if (wallObject.getId() != SARCOPHAGUS_WALL_ID) {
            return;
        }

        if (hasEnabledDelivery()) {
            ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
            clientThread.invokeAtTickEnd(() -> notifyPurpleAmascut(profiles));
        }
    }

    public void onTick() {
        if (cachedPlayerName == null) {
            cachedPlayerName = Utils.getPlayerName(client);
        }
        if (loginTicks.getAndUpdate(i -> Math.max(-1, i - 1)) == 0 && hasEnabledDelivery()) {
            ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
            clientThread.invokeLater(() -> notifyLogin(profiles)); // just 20ms later to be able to run client scripts cleanly
        }
    }

    public void reset() {
        cachedPlayerName = null;
    }

    public void onVarbit(VarbitChanged event) {
        if (event.getVarbitId() == VarbitID.TOA_VAULT_SARCOPHAGUS) {
            isToaPurple = event.getValue() % 2 == 1;
        }
    }

    public void onWidget(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.SHARED_BANK && hasEnabledDelivery()) {
            ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
            clientThread.invokeLater(() -> notifyGroupStorage(profiles));
        }
    }

    private void notifyGroupStorage(ProfileRuntimeSnapshot profiles) {
        ItemContainer bank = client.getItemContainer(InventoryID.INV_GROUP_TEMP);
        if (bank == null) return;

        Item[] array = bank.getItems();
        List<SerializedItemStack> items = new ArrayList<>(array.length);
        long totalValue = 0;
        for (Item i : array) {
            if (i == null || i.getId() < 0) continue;

            int itemId = ItemUtils.canonicalizeItem(itemManager, i.getId());
            SerializedItemStack item = ItemUtils.stackFromItem(itemManager, itemId, i.getQuantity());
            items.add(item);
            totalValue += item.getTotalPrice();
        }

        // Fire notification
        int slots = client.getVarpValue(VarPlayerID.IF3);
        String playerName = Utils.getPlayerName(client);
        Template message = Template.builder()
            .replacementBoundary("%")
            .template("%USERNAME% opened the GIM shared bank containing %ITEM_COUNT% items worth %TOTAL_VALUE% with %SLOT_COUNT% slots unlocked")
            .replacement("%USERNAME%", Replacements.ofText(playerName))
            .replacement("%ITEM_COUNT%", Replacements.ofText(String.valueOf(items.size())))
            .replacement("%TOTAL_VALUE%", Replacements.ofText(QuantityFormatter.quantityToStackSize(totalValue)))
            .replacement("%SLOT_COUNT%", Replacements.ofText(String.valueOf(slots)))
            .build();
        var extra = new GroupBankContentsNotificationData(items, slots);
        deliverMetadata(profiles, NotificationBody.builder()
            .type(NotificationType.GROUP_BANK_CONTENTS)
            .text(message)
            .extra(extra)
            .playerName(playerName)
            .build()
        );
    }

    private void notifyPurpleAmascut(ProfileRuntimeSnapshot profiles) {
        if (isToaPurple) {
            isToaPurple = false; // prevent multiple notifications
        } else {
            return; // not notification worthy
        }

        // inspect multiloc to ensure local player is the recipient of the purple drop (s/o @rdutta)
        for (@Varbit int varbitId : TOA_CHEST_VARBS) {
            if (client.getVarbitValue(varbitId) == 2) {
                // someone else in the party received the purple drop
                return;
            }
        }

        // Gather relevant data
        var party = Utils.getAmascutTombsParty(client);
        int rewardPoints = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSCORE);
        int raidLevels = client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);

        // Calculate probability based on https://oldschool.runescape.wiki/w/Chest_(Tombs_of_Amascut)#Uniques
        int x = Math.min(raidLevels, 400);
        int y = Math.max(Math.min(raidLevels, 550) - 400, 0);
        int partySize = Math.max(party.size(), 1);
        double probability = Math.min(0.01 * rewardPoints / (10_500 - 20 * (x + y / 3.0)), 0.55) / partySize;

        // Fire notification
        String playerName = Utils.getPlayerName(client);
        Template message = Template.builder()
            .replacementBoundary("%")
            .template("%USERNAME% rolled a purple (unique) drop from Tombs of Amascut!")
            .replacement("%USERNAME%", Replacements.ofText(playerName))
            .build();
        var extra = new AmascutPurpleNotificationData(party, rewardPoints, raidLevels, probability);
        deliverMetadata(profiles, NotificationBody.builder()
            .type(NotificationType.TOA_UNIQUE)
            .text(message)
            .extra(extra)
            .playerName(playerName)
            .build()
        );
    }

    private void notifyLogin(ProfileRuntimeSnapshot profiles) {
        // Gather data points
        int world = client.getWorld();

        int collectionCompleted = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
        int collectionTotal = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);

        int combatAchievementPoints = client.getVarbitValue(VarbitID.CA_POINTS);
        int combatAchievementPointsTotal = client.getVarbitValue(VarbitID.CA_THRESHOLD_GRANDMASTER);

        int diaryCompleted = AchievementDiary.DIARIES.keySet()
            .stream()
            .mapToInt(id -> DiaryNotifier.isComplete(id, client.getVarbitValue(id)) ? 1 : 0)
            .sum();
        int diaryTotal = AchievementDiary.DIARIES.size();
        client.runScript(DiaryNotifier.COMPLETED_TASKS_SCRIPT_ID);
        int diaryTaskCompleted = client.getIntStack()[0];
        client.runScript(DiaryNotifier.TOTAL_TASKS_SCRIPT_ID);
        int diaryTaskTotal = client.getIntStack()[0];

        int gambleCount = client.getVarbitValue(VarbitID.BARBASSAULT_GAMBLECOUNT);

        long experienceTotal = client.getOverallExperience();
        int levelTotal = client.getTotalLevel();
        Map<String, Integer> skillLevels = new HashMap<>(32);
        Map<String, Integer> skillExperience = new HashMap<>(32);
        for (Skill skill : Skill.values()) {
            int xp = client.getSkillExperience(skill);
            int lvl = client.getRealSkillLevel(skill);
            int virtualLevel = lvl < 99 ? lvl : Experience.getLevelForXp(xp);
            skillExperience.put(skill.getName(), xp);
            skillLevels.put(skill.getName(), virtualLevel);
        }

        int questsCompleted = client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT);
        int questsTotal = client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT);
        int questPoints = client.getVarpValue(VarPlayerID.QP);
        int questPointsTotal = client.getVarbitValue(VarbitID.QP_MAX);

        int slayerPoints = client.getVarbitValue(VarbitID.SLAYER_POINTS);
        int slayerStreak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);

        // Fire notification
        String playerName = Utils.getPlayerName(client);
        cachedPlayerName = playerName;

        Template message = Template.builder()
            .replacementBoundary("%")
            .template("%USERNAME% logged into World %WORLD%")
            .replacement("%USERNAME%", Replacements.ofText(playerName))
            .replacement("%WORLD%", Replacements.ofText(String.valueOf(world)))
            .build();
        LoginNotificationData extra = new LoginNotificationData(
            world,
            Progress.of(collectionCompleted, collectionTotal),
            Progress.of(combatAchievementPoints, combatAchievementPointsTotal),
            Progress.of(diaryCompleted, diaryTotal),
            Progress.of(diaryTaskCompleted, diaryTaskTotal),
            new LoginNotificationData.BarbarianAssault(gambleCount),
            new LoginNotificationData.SkillData(experienceTotal, levelTotal, skillLevels, skillExperience),
            Progress.of(questsCompleted, questsTotal),
            Progress.of(questPoints, questPointsTotal),
            new LoginNotificationData.SlayerData(slayerPoints, slayerStreak),
            getPets()
        );
        deliverMetadata(profiles, NotificationBody.builder()
            .type(NotificationType.LOGIN)
            .text(message)
            .extra(extra)
            .playerName(playerName)
            .build()
        );
    }

    private void notifyLogout(ProfileRuntimeSnapshot profiles) {
        String playerName = Utils.getPlayerName(client);
        // Fallback if playerName is null.
        // It will use a cached player name which is set in notifyLogin.
        if (playerName == null) {
            playerName = cachedPlayerName;
        }

        Template message = Template.builder()
            .replacementBoundary("%")
            .template("%USERNAME% logged out")
            .replacement("%USERNAME%", Replacements.ofText(playerName))
            .build();

        deliverMetadata(profiles, NotificationBody.builder()
            .type(NotificationType.LOGOUT)
            .text(message)
            .playerName(playerName)
            .build()
        );
        cachedPlayerName = null;
    }

    private boolean hasEnabledDelivery() {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        return profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return StringUtils.isNotBlank(profile.metadataWebhook())
            && profileEligibilityService.isEligible(profile);
    }

    private void deliverMetadata(ProfileRuntimeSnapshot profiles, NotificationBody<?> body) {
        if (profiles.isProfilesConfigured()) {
            NotificationBody<?> outbound = null;
            for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
                if (!isProfileEnabled(profile)) continue;
                if (deliver(profile, profile.metadataWebhook(), false, body) && outbound == null) outbound = body;
            }
            if (outbound != null) publishPluginMessage(outbound);
            return;
        }
        createMessage(false, body);
    }

    @VisibleForTesting
    List<SerializedPet> getPets() {
        if (ConfigUtil.isPluginDisabled(configManager, RL_CHAT_CMD_PLUGIN_NAME))
            return null;

        String json = configManager.getRSProfileConfiguration("chatcommands", "pets2");
        if (json == null || json.isEmpty())
            return null;

        int[] petItemIds;
        try {
            petItemIds = gson.fromJson(json, int[].class);
        } catch (JsonSyntaxException e) {
            log.info("Failed to deserialize owned pet IDs", e);
            return null;
        }

        List<SerializedPet> pets = new ArrayList<>(petItemIds.length);
        for (int itemId : petItemIds) {
            pets.add(new SerializedPet(itemId, client.getItemDefinition(itemId).getMembersName()));
        }
        return pets;
    }

    static {
        TOA_CHEST_VARBS = new int[] {
            VarbitID.TOA_VAULT_CHEST_0, VarbitID.TOA_VAULT_CHEST_1, VarbitID.TOA_VAULT_CHEST_2, VarbitID.TOA_VAULT_CHEST_3,
            VarbitID.TOA_VAULT_CHEST_4, VarbitID.TOA_VAULT_CHEST_5, VarbitID.TOA_VAULT_CHEST_6, VarbitID.TOA_VAULT_CHEST_7
        };
    }
}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Evaluable;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.message.templating.impl.JoiningReplacement;
import pigeon.util.Utils;
import pigeon.notifiers.data.SlayerNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Singleton;
import javax.inject.Inject;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Singleton
public class SlayerNotifier extends BaseNotifier {
    private static final Pattern BOSS_REGEX = Pattern.compile("You are granted .+ Slayer XP for completing your boss task against(?: the)? (?<name>.+)\\.$");
    @VisibleForTesting
    static final Pattern SLAYER_TASK_REGEX = Pattern.compile("You have completed your task! You killed (?<task>[\\d,]+ [^.]+)\\..*");
    private static final Pattern SLAYER_COMPLETE_REGEX = Pattern.compile("You've completed (?:at least )?(?<taskCount>[\\d,]+) (?:Wilderness |Mortimer )?tasks?(?: and received (?<points>[\\d,]+) points, giving you a total of [\\d,]+|\\.You'll be eligible to earn reward points if you complete tasks from a more advanced Slayer Master\\.| and reached the maximum amount of Slayer points \\((?<points2>[\\d,]+)\\))?");
    private static final Pattern TASK_MONSTER_REGEX = Pattern.compile("^(?<count>\\d*)\\s*(?<monster>.+)$");

    private final AtomicReference<String> slayerTask = new AtomicReference<>("");
    private final AtomicInteger badTicks = new AtomicInteger(); // used to prevent notifs from using stale data
    private ProfileRuntimeSnapshot pendingProfileSnapshot;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        return config.notifySlayer() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.slayerWebhook();
    }

    public void onChatMessage(String chatMessage) {
        ProfileRuntimeSnapshot profiles = pendingProfileSnapshot != null
            ? pendingProfileSnapshot : profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (enabled) {
            if (slayerTask.get().isEmpty()) {
                Matcher bossMatcher = BOSS_REGEX.matcher(chatMessage);
                if (bossMatcher.find()) {
                    String name = bossMatcher.group("name");
                    this.slayerTask.set(name.endsWith(" boss") ? name.substring(0, name.length() - " boss".length()) : name);
                    rememberSnapshot(profiles);
                    return;
                }
            }

            Matcher taskMatcher = SLAYER_TASK_REGEX.matcher(chatMessage);
            if (taskMatcher.find()) {
                String task = taskMatcher.group("task");
                slayerTask.getAndUpdate(old -> {
                    if (old == null || old.isEmpty())
                        return task;
                    return String.format("%s %s", task.substring(0, task.indexOf(' ')), old);
                });
                rememberSnapshot(profiles);
                return;
            }

            if (slayerTask.get().isEmpty()) {
                return;
            }

            Matcher pointsMatcher = SLAYER_COMPLETE_REGEX.matcher(chatMessage);
            if (pointsMatcher.find()) {
                String slayerPoints = pointsMatcher.group("points");
                String slayerTasksCompleted = pointsMatcher.group("taskCount");

                if (slayerPoints == null) {
                    slayerPoints = pointsMatcher.group("points2");
                }

                // 3 different cases of seeing points, so in our worst case it's 0
                if (slayerPoints == null) {
                    slayerPoints = "0";
                }

                if (pendingProfileSnapshot != null && pendingProfileSnapshot.isProfilesConfigured()) {
                    this.handleProfileNotify(slayerPoints, slayerTasksCompleted, pendingProfileSnapshot);
                } else {
                    this.handleNotify(slayerPoints, slayerTasksCompleted);
                }
            }
        }
    }

    public void onTick() {
        // Track how many ticks occur where we only have partial slayer data
        if (!slayerTask.get().isEmpty())
            badTicks.getAndIncrement();

        // Clear data if 2 ticks pass with only partial parsing
        if (badTicks.get() > 1)
            reset();
    }

    private void handleNotify(String slayerPoints, String slayerCompleted) {
        String task = slayerTask.get();
        if (task.isEmpty() || slayerPoints.isEmpty() || slayerCompleted.isEmpty()) {
            return;
        }

        int threshold = config.slayerPointThreshold();
        if (threshold <= 0 || Integer.parseInt(slayerPoints.replace(",", "")) >= threshold) {
            Optional<Pair<Integer, String>> parsedTask = parseTask(task);
            Integer marginalKillCount = parsedTask.map(Pair::getLeft).orElse(null);
            String monster = parsedTask.map(Pair::getRight).orElse(null);

            Template notifyMessage = Template.builder()
                .template(config.slayerNotifyMessage())
                .replacementBoundary("%")
                .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
                .replacement("%TASK%", buildTask(task, monster, marginalKillCount))
                .replacement("%TASKCOUNT%", Replacements.ofText(slayerCompleted))
                .replacement("%POINTS%", Replacements.ofText(slayerPoints))
                .build();

            createMessage(config.slayerSendImage(), NotificationBody.builder()
                .text(notifyMessage)
                .extra(new SlayerNotificationData(task, slayerCompleted, slayerPoints, marginalKillCount, monster))
                .type(NotificationType.SLAYER)
                .build());
        }

        this.reset();
    }

    private void handleProfileNotify(String slayerPoints, String slayerCompleted,
                                     ProfileRuntimeSnapshot profiles) {
        String task = slayerTask.get();
        if (task.isEmpty() || slayerPoints.isEmpty() || slayerCompleted.isEmpty()) return;

        int points = Integer.parseInt(slayerPoints.replace(",", ""));
        Optional<Pair<Integer, String>> parsedTask = parseTask(task);
        Integer marginalKillCount = parsedTask.map(Pair::getLeft).orElse(null);
        String monster = parsedTask.map(Pair::getRight).orElse(null);
        SlayerNotificationData extra = new SlayerNotificationData(
            task, slayerCompleted, slayerPoints, marginalKillCount, monster);

        NotificationBody<?> outbound = null;
        for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
            int threshold = profile.slayerPointThreshold();
            if (!isProfileEnabled(profile) || (threshold > 0 && points < threshold)) continue;

            NotificationBody<?> body = createBody(
                profile, task, slayerPoints, slayerCompleted, marginalKillCount, monster, extra);
            if (deliver(profile, profile.slayerWebhook(), profile.slayerSendImage(), body)
                && outbound == null) {
                outbound = body;
            }
        }
        if (outbound != null) publishPluginMessage(outbound);
        reset();
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, String task, String slayerPoints,
                                            String slayerCompleted, Integer marginalKillCount,
                                            String monster, SlayerNotificationData extra) {
        Template notifyMessage = Template.builder()
            .template(deliveryConfig.slayerNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
            .replacement("%TASK%", buildTask(task, monster, marginalKillCount))
            .replacement("%TASKCOUNT%", Replacements.ofText(slayerCompleted))
            .replacement("%POINTS%", Replacements.ofText(slayerPoints))
            .build();
        return NotificationBody.builder()
            .text(notifyMessage)
            .extra(extra)
            .type(NotificationType.SLAYER)
            .build();
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifySlayer() && profileEligibilityService.isEligible(profile);
    }

    private void rememberSnapshot(ProfileRuntimeSnapshot profiles) {
        if (pendingProfileSnapshot == null && profiles.isProfilesConfigured()) {
            pendingProfileSnapshot = profiles;
        }
    }

    public void reset() {
        slayerTask.set("");
        badTicks.set(0);
        pendingProfileSnapshot = null;
    }

    @NotNull
    private static Evaluable buildTask(@NotNull String rawTask, @Nullable String monster, @Nullable Integer count) {
        if (count == null || monster == null)
            return Replacements.ofText(rawTask);

        return JoiningReplacement.builder()
            .component(Replacements.ofText(String.valueOf(count)))
            .delimiter(" ")
            .component(Replacements.ofWiki(monster))
            .build();
    }

    @NotNull
    private static Optional<Pair<Integer, String>> parseTask(@NotNull String task) {
        Matcher m = TASK_MONSTER_REGEX.matcher(task);
        if (!m.find()) return Optional.empty();
        return Optional.of(Pair.of(Integer.parseInt(m.group("count")), m.group("monster")));
    }
}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.domain.AccountType;
import pigeon.domain.Danger;
import pigeon.domain.ExceptionalDeath;
import pigeon.message.Embed;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.notifiers.data.DeathNotificationData;
import pigeon.notifiers.data.SerializedItemStack;
import pigeon.profiles.PigeonProfileConfig;
