package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.domain.AchievementDiary;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.notifiers.data.DiaryNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import pigeon.util.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static pigeon.domain.AchievementDiary.DIARIES;

@Slf4j
@Singleton
public class DiaryNotifier extends BaseNotifier {

    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bproc,script3971%5D.cs2">CS2 Reference</a>
     */
    static final int COMPLETED_TASKS_SCRIPT_ID = 3971;

    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bproc,script3980%5D.cs2">CS2 Reference</a>
     */
    static final int TOTAL_TASKS_SCRIPT_ID = 3980;

    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bproc,summary_diary_completed%5D.cs2">CS2 Reference</a>
     */
    private static final int COMPLETED_AREA_TASKS_SCRIPT_ID = 4072;

    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bproc,summary_diary_total%5D.cs2">CS2 Reference</a>
     */
    private static final int TOTAL_AREA_TASKS_SCRIPT_ID = 4073;

    private static final Pattern COMPLETION_REGEX = Pattern.compile("Congratulations! You have completed all of the (?<difficulty>.+) tasks in the (?<area>.+) area");
    private final Map<Integer, Integer> diaryCompletionById = new ConcurrentHashMap<>();
    private final AtomicInteger initDelayTicks = new AtomicInteger();
    private final AtomicInteger cooldownTicks = new AtomicInteger();

    @Inject
    private ClientThread clientThread;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        return config.notifyAchievementDiary() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.diaryWebhook();
    }

    public void reset() {
        this.diaryCompletionById.clear();
        this.initDelayTicks.set(0);
        this.cooldownTicks.set(0);
    }

    public void onGameState(GameStateChanged event) {
        if (event.getGameState() != GameState.LOGGED_IN)
            this.reset();
    }

    public void onTick() {
        if (client.getGameState() != GameState.LOGGED_IN)
            return;

        cooldownTicks.getAndUpdate(i -> Math.max(i - 1, 0));
        int ticks = initDelayTicks.getAndUpdate(i -> Math.max(i - 1, 0));
        if (ticks > 0) {
            if (ticks == 1) {
                this.initCompleted();
            }
        } else if (diaryCompletionById.size() < DIARIES.size() && super.isEnabled()) {
            // mark diary completions to be initialized later
            this.initDelayTicks.set(4);
        }
    }

    public void onMessageBox(String message) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (!enabled) return;

        Matcher matcher = COMPLETION_REGEX.matcher(message);
        if (matcher.find()) {
            String difficultyStr = matcher.group("difficulty");
            AchievementDiary.Difficulty difficulty;
            try {
                difficulty = AchievementDiary.Difficulty.valueOf(difficultyStr.toUpperCase());
            } catch (IllegalArgumentException e) {
                log.warn("Failed to match diary difficulty: {}", difficultyStr);
                return;
            }

            String area = matcher.group("area").trim();
            Optional<AchievementDiary> found = DIARIES.values().stream()
                .filter(e -> e.getDifficulty() == difficulty && Utils.containsEither(e.getArea(), area))
                .findAny();
            if (found.isPresent()) {
                AchievementDiary diary = found.get();
                int varbitId = diary.getId();
                if (isComplete(varbitId, 1)) {
                    diaryCompletionById.put(varbitId, 1);
                } else {
                    diaryCompletionById.put(varbitId, 2);
                }
                boolean notify = profiles.isProfilesConfigured()
                    ? profiles.getEnabledProfiles().stream().anyMatch(profile ->
                        isProfileEnabled(profile) && checkDifficulty(profile, difficulty))
                    : checkDifficulty(difficulty);
                if (!notify) return;

                clientThread.invokeLater(() -> handle(diary, profiles)); // 20ms delay to run scripts cleanly
            } else {
                log.warn("Failed to match diary area: {}", area);
            }
        }
    }

    public void onVarbitChanged(VarbitChanged event) {
        int id = event.getVarbitId();
        if (id < 0) return;
        AchievementDiary diary = DIARIES.get(id);
        if (diary == null) return;
        if (!super.isEnabled()) return;
        if (diaryCompletionById.isEmpty()) {
            if (client.getGameState() == GameState.LOGGED_IN && isComplete(id, event.getValue())) {
                // this log only occurs in exceptional circumstances (i.e., completion within seconds of logging in or enabling the plugin)
                log.info("Skipping {} {} diary completion that occurred before map initialization", diary.getDifficulty(), diary.getArea());
            }
            return;
        }

        int value = event.getValue();
        Integer previous = diaryCompletionById.get(id);
        if (previous == null) {
            // this log should not occur, barring a jagex oddity
            log.warn("Resetting since {} {} diary was not initialized with a valid value; received new value of {}", diary.getDifficulty(), diary.getArea(), value);
            reset();
        } else if (value < previous) {
            // this log should not occur, barring a jagex/runelite oddity
            log.info("Resetting since it appears {} {} diary has lost progress from {}; received new value of {}", diary.getDifficulty(), diary.getArea(), previous, value);
            reset();
        } else if (value > previous) {
            diaryCompletionById.put(id, value);

            if (isComplete(id, value)) {
                ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
                boolean notify = profiles.isProfilesConfigured()
                    ? profiles.getEnabledProfiles().stream().anyMatch(profile ->
                        isProfileEnabled(profile) && checkDifficulty(profile, diary.getDifficulty()))
                    : checkDifficulty(diary.getDifficulty());
                if (notify) {
                    clientThread.invokeLater(() -> handle(diary, profiles)); // 20ms delay to run scripts cleanly
                } else {
                    log.debug("Skipping {} {} diary due to low difficulty", diary.getDifficulty(), diary.getArea());
                }
            } else {
                // Karamja special case
                log.info("Skipping {} {} diary start (not a completion with value {})", diary.getDifficulty(), diary.getArea(), value);
            }
        }
    }

    private void handle(AchievementDiary diary, ProfileRuntimeSnapshot profiles) {
        if (cooldownTicks.getAndSet(2) > 0) {
            log.debug("Skipping diary completion during cooldown: {} {}", diary.getDifficulty(), diary.getArea());
            return;
        }

        client.runScript(DiaryNotifier.COMPLETED_TASKS_SCRIPT_ID);
        int completedTasks = client.getIntStack()[0];
        client.runScript(DiaryNotifier.TOTAL_TASKS_SCRIPT_ID);
        int totalTasks = client.getIntStack()[0];

        client.runScript(COMPLETED_AREA_TASKS_SCRIPT_ID, diary.getAreaId());
        int completedAreaTasks = client.getIntStack()[0];
        client.runScript(TOTAL_AREA_TASKS_SCRIPT_ID, diary.getAreaId());
        int totalAreaTasks = client.getIntStack()[0];

        int completedDiaries = getTotalCompleted();
        String player = Utils.getPlayerName(client);
        DiaryNotificationData extra = new DiaryNotificationData(
            diary.getArea(), diary.getDifficulty(), completedDiaries, completedTasks,
            totalTasks, completedAreaTasks, totalAreaTasks);
        if (profiles.isProfilesConfigured()) {
            NotificationBody<?> outbound = null;
            for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
                if (!isProfileEnabled(profile) || !checkDifficulty(profile, diary.getDifficulty())) continue;
                NotificationBody<?> body = createBody(profile, diary, completedDiaries, completedTasks,
                    totalTasks, completedAreaTasks, totalAreaTasks, player, extra);
                if (deliver(profile, profile.diaryWebhook(), profile.diarySendImage(), body)
                    && outbound == null) outbound = body;
            }
            if (outbound != null) publishPluginMessage(outbound);
            return;
        }

        NotificationBody<?> body = createBody(config, diary, completedDiaries, completedTasks,
            totalTasks, completedAreaTasks, totalAreaTasks, player, extra);
        createMessage(config.diarySendImage(), body);
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, AchievementDiary diary,
                                            int completedDiaries, int completedTasks, int totalTasks,
                                            int completedAreaTasks, int totalAreaTasks, String player,
                                            DiaryNotificationData extra) {
        Template message = Template.builder()
            .template(deliveryConfig.diaryNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(player))
            .replacement("%DIFFICULTY%", Replacements.ofText(diary.getDifficulty().toString()))
            .replacement("%AREA%", Replacements.ofWiki(diary.getArea(), diary.getArea() + " Diary"))
            .replacement("%TOTAL%", Replacements.ofText(String.valueOf(completedDiaries)))
            .replacement("%TASKS_COMPLETE%", Replacements.ofText(String.valueOf(completedTasks)))
            .replacement("%TASKS_TOTAL%", Replacements.ofText(String.valueOf(totalTasks)))
            .replacement("%AREA_TASKS_COMPLETE%", Replacements.ofText(String.valueOf(completedAreaTasks)))
            .replacement("%AREA_TASKS_TOTAL%", Replacements.ofText(String.valueOf(totalAreaTasks)))
            .build();

        return NotificationBody.builder()
            .type(NotificationType.ACHIEVEMENT_DIARY)
            .text(message)
            .extra(extra)
            .playerName(player)
            .build();
    }

    private boolean checkDifficulty(AchievementDiary.Difficulty difficulty) {
        return checkDifficulty(config, difficulty);
    }

    private boolean checkDifficulty(PigeonConfig deliveryConfig, AchievementDiary.Difficulty difficulty) {
        return deliveryConfig.notifyAchievementDiary()
            && difficulty.ordinal() >= deliveryConfig.minDiaryDifficulty().ordinal();
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyAchievementDiary() && profileEligibilityService.isEligible(profile);
    }

    private int getTotalCompleted() {
        int n = 0;

        for (Map.Entry<Integer, Integer> entry : diaryCompletionById.entrySet()) {
            int id = entry.getKey();
            int value = entry.getValue();
            if (isComplete(id, value)) {
                n++;
            }
        }

        return n;
    }

    private void initCompleted() {
        if (!super.isEnabled()) return;
        for (Integer id : DIARIES.keySet()) {
            int value = client.getVarbitValue(id);
            if (value >= 0) {
                diaryCompletionById.put(id, value);
            }
        }
        log.debug("Finished initializing current diary completions: {} out of {}", getTotalCompleted(), diaryCompletionById.size());
    }

    public static boolean isComplete(int id, int value) {
        if (id == 3578 || id == 3599 || id == 3611) {
            // Karamja special case (except Elite): 0 = not started, 1 = started, 2 = completed tasks
            return value > 1;
        } else {
            // otherwise: 0 = not started, 1 = completed
            return value > 0;
        }
    }
}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.domain.ClueTier;
import pigeon.message.Embed;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Evaluable;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.message.templating.impl.JoiningReplacement;
import pigeon.util.ItemUtils;
import pigeon.util.Utils;
import pigeon.notifiers.data.ClueNotificationData;
import pigeon.notifiers.data.SerializedItemStack;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;
import org.jetbrains.annotations.Nullable;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class ClueNotifier extends BaseNotifier {
    private static final Pattern CLUE_SCROLL_REGEX = Pattern.compile("You have completed (?<scrollCount>\\d+) (?<scrollType>\\w+) Treasure Trails?\\.");
    private final AtomicInteger badTicks = new AtomicInteger(); // used to prevent notifs from using stale data
    private volatile int clueCount = -1;
    private volatile String clueType = "";
    private ProfileRuntimeSnapshot pendingProfileSnapshot;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        return config.notifyClue() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.clueWebhook();
    }

    public void onChatMessage(String chatMessage) {
        Map.Entry<String, Integer> result = parse(chatMessage);
        if (result != null) {
            ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
            boolean enabled = profiles.isProfilesConfigured()
                ? profiles.getEnabledProfiles().stream().anyMatch(profile ->
                    isProfileEnabled(profile) && checkClueTier(profile, result.getKey()))
                : isEnabled() && checkClueTier(result.getKey());
            if (enabled) {
                // game message always occurs before widget load; save this data
                this.clueCount = result.getValue();
                this.clueType = result.getKey();
                if (profiles.isProfilesConfigured()) pendingProfileSnapshot = profiles;
            }
        }
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        boolean enabled = pendingProfileSnapshot != null
            ? pendingProfileSnapshot.getEnabledProfiles().stream().anyMatch(profile ->
                isProfileEnabled(profile) && checkClueTier(profile, clueType))
            : isEnabled();
        if (event.getGroupId() == InterfaceID.TRAIL_REWARDSCREEN && enabled) {
            Widget clue = client.getWidget(InterfaceID.TrailRewardscreen.ITEMS);
            if (clue != null && !clueType.isEmpty()) {
                Widget[] children = clue.getChildren();
                if (children == null) return;

                Map<Integer, Integer> clueItems = new HashMap<>();
                for (Widget child : children) {
                    if (child == null) continue;

                    int quantity = child.getItemQuantity();
                    int itemId = child.getItemId();
                    if (itemId > -1 && quantity > 0) {
                        clueItems.merge(itemId, quantity, Integer::sum);
                    }
                }

                if (pendingProfileSnapshot != null) handleProfileNotify(clueItems, pendingProfileSnapshot);
                else handleNotify(clueItems);
            }
        }
    }

    public void onTick() {
        // Track how many ticks occur where we only have partial clue data
        if (!clueType.isEmpty())
            badTicks.getAndIncrement();

        // Clear data if 2 ticks pass with only partial parsing (both events should occur within same tick)
        if (badTicks.get() > 1)
            reset();
    }

    private void handleNotify(Map<Integer, Integer> clueItems) {
        JoiningReplacement.JoiningReplacementBuilder lootMessage = JoiningReplacement.builder().delimiter("\n");
        AtomicLong totalPrice = new AtomicLong();
        List<SerializedItemStack> itemStacks = new ArrayList<>(clueItems.size());
        List<Embed> embeds = new ArrayList<>(config.clueShowItems() ? clueItems.size() : 0);

        clueItems.forEach((itemId, quantity) -> {
            SerializedItemStack stack = ItemUtils.stackFromItem(itemManager, itemId, quantity);
            totalPrice.addAndGet(stack.getTotalPrice());
            itemStacks.add(stack);
            lootMessage.component(getItemMessage(stack, embeds));
        });

        if (totalPrice.get() >= config.clueMinValue()) {
            boolean screenshot = config.clueSendImage() && totalPrice.get() >= config.clueImageMinValue();
            Template notifyMessage = Template.builder()
                .template(config.clueNotifyMessage())
                .replacementBoundary("%")
                .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
                .replacement("%CLUE%", Replacements.ofWiki(clueType, "Clue scroll (" + clueType + ")"))
                .replacement("%COUNT%", Replacements.ofText(String.valueOf(clueCount)))
                .replacement("%TOTAL_VALUE%", Replacements.ofText(QuantityFormatter.quantityToStackSize(totalPrice.get())))
                .replacement("%LOOT%", lootMessage.build())
                .build();
            String icon = String.format("https://oldschool.runescape.wiki/images/Clue_scroll_(%s).png", clueType.toLowerCase());
            createMessage(screenshot,
                NotificationBody.builder()
                    .text(notifyMessage)
                    .extra(new ClueNotificationData(clueType, clueCount, itemStacks))
                    .type(NotificationType.CLUE)
                    .embeds(embeds)
                    .thumbnailUrl(icon)
                    .build()
            );
        }

        this.reset();
    }

    private void handleProfileNotify(Map<Integer, Integer> clueItems, ProfileRuntimeSnapshot profiles) {
        JoiningReplacement.JoiningReplacementBuilder lootMessage = JoiningReplacement.builder().delimiter("\n");
        long totalPrice = 0;
        List<SerializedItemStack> itemStacks = new ArrayList<>(clueItems.size());
        for (Map.Entry<Integer, Integer> item : clueItems.entrySet()) {
            SerializedItemStack stack = ItemUtils.stackFromItem(
                itemManager, item.getKey(), item.getValue());
            totalPrice += stack.getTotalPrice();
            itemStacks.add(stack);
            lootMessage.component(ItemUtils.templateStack(stack, true));
        }

        ClueNotificationData extra = new ClueNotificationData(clueType, clueCount, itemStacks);
        String icon = String.format(
            "https://oldschool.runescape.wiki/images/Clue_scroll_(%s).png", clueType.toLowerCase());
        NotificationBody<?> outbound = null;
        for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
            if (!isProfileEnabled(profile) || !checkClueTier(profile, clueType)
                || totalPrice < profile.clueMinValue()) continue;

            List<Embed> embeds = profile.clueShowItems()
                ? itemStacks.stream().map(item -> Embed.ofImage(ItemUtils.getItemImageUrl(item.getId())))
                    .collect(java.util.stream.Collectors.toList())
                : List.of();
            Template notifyMessage = Template.builder()
                .template(profile.clueNotifyMessage())
                .replacementBoundary("%")
                .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
                .replacement("%CLUE%", Replacements.ofWiki(clueType, "Clue scroll (" + clueType + ")"))
                .replacement("%COUNT%", Replacements.ofText(String.valueOf(clueCount)))
                .replacement("%TOTAL_VALUE%", Replacements.ofText(QuantityFormatter.quantityToStackSize(totalPrice)))
                .replacement("%LOOT%", lootMessage.build())
                .build();
            NotificationBody<?> body = NotificationBody.builder()
                .text(notifyMessage)
                .extra(extra)
                .type(NotificationType.CLUE)
                .embeds(embeds)
                .thumbnailUrl(icon)
                .build();
            boolean screenshot = profile.clueSendImage() && totalPrice >= profile.clueImageMinValue();
            if (deliver(profile, profile.clueWebhook(), screenshot, body) && outbound == null) outbound = body;
        }
        if (outbound != null) publishPluginMessage(outbound);
        reset();
    }

    private Evaluable getItemMessage(SerializedItemStack item, Collection<Embed> embeds) {
        if (config.clueShowItems())
            embeds.add(Embed.ofImage(ItemUtils.getItemImageUrl(item.getId())));
        return ItemUtils.templateStack(item, true);
    }

    private boolean checkClueTier(String clueType) {
        return checkClueTier(config, clueType);
    }

    private boolean checkClueTier(PigeonConfig deliveryConfig, String clueType) {
        ClueTier tier = ClueTier.parse(clueType);
        if (tier == null) {
            log.warn("Failed to parse clue tier: {}", clueType);
            return true; // permissive approach
        }
        return tier.ordinal() >= deliveryConfig.clueMinTier().ordinal();
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyClue() && profileEligibilityService.isEligible(profile);
    }

    public void reset() {
        this.clueCount = -1;
        this.clueType = "";
        this.badTicks.set(0);
        this.pendingProfileSnapshot = null;
    }

    @Nullable
    public static Map.Entry<String, Integer> parse(String gameMessage) {
        Matcher clueMatcher = CLUE_SCROLL_REGEX.matcher(gameMessage);
        if (!clueMatcher.find()) return null;
        String tier = clueMatcher.group("scrollType");
        String count = clueMatcher.group("scrollCount");
        return Map.entry(tier, Integer.parseInt(count));
    }

}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.notifiers.data.SpeedrunNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import pigeon.util.QuestUtils;
import pigeon.util.TimeUtils;
import pigeon.util.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import java.time.Duration;
import javax.inject.Inject;

@Slf4j
public class SpeedrunNotifier extends BaseNotifier {
    private boolean isPersonalBest = false;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        // intentionally doesn't call super as WorldUtils.isIgnoredWorld includes speedrunning
        return config.notifySpeedrun() && accountTracker.hasValidState();
    }

    @Override
    protected String getWebhookUrl() {
        return config.speedrunWebhook();
    }

    public void reset() {
        isPersonalBest = false;
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (event.getGroupId() == InterfaceID.QUESTSCROLL_SPEEDRUN && enabled) {
            Widget questName = client.getWidget(InterfaceID.QuestscrollSpeedrun.QUEST_TITLE);
            Widget duration = client.getWidget(InterfaceID.QuestscrollSpeedrun.TIME_TEXT);
            Widget personalBest = client.getWidget(InterfaceID.QuestscrollSpeedrun.BEST_TEXT);
            if (questName != null && duration != null && personalBest != null) {
                this.attemptNotify(QuestUtils.parseQuestWidget(questName.getText()), duration.getText(),
                    personalBest.getText(), profiles);
            } else {
                log.warn("Found speedrun finished widget (group id {}) but it is missing something, questName={}, duration={}, pb={}", event.getGroupId(), questName, duration, personalBest);
            }
        }
    }

    private void attemptNotify(String questName, String duration, String pb, ProfileRuntimeSnapshot profiles) {
        if (!profiles.isProfilesConfigured() && !isPersonalBest && config.speedrunPBOnly()) {
            return;
        }

        // Reformat the durations for the extra object
        Duration bestTime = TimeUtils.parseTime(pb);
        Duration currentTime = TimeUtils.parseTime(duration);

        SpeedrunNotificationData extra = new SpeedrunNotificationData(
            questName, bestTime.toString(), currentTime.toString(), isPersonalBest);
        if (profiles.isProfilesConfigured()) {
            NotificationBody<?> outbound = null;
            for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
                if (!isProfileEnabled(profile) || (!isPersonalBest && profile.speedrunPBOnly())) continue;
                NotificationBody<?> body = createBody(profile, questName, duration, pb, extra);
                if (deliver(profile, profile.speedrunWebhook(), profile.speedrunSendImage(), body)
                    && outbound == null) outbound = body;
            }
            if (outbound != null) publishPluginMessage(outbound);
            this.reset();
            return;
        }

        createMessage(config.speedrunSendImage(), createBody(config, questName, duration, pb, extra));
        this.reset();
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, String questName,
                                            String duration, String pb, SpeedrunNotificationData extra) {
        Template notifyMessage = Template.builder()
            .template(isPersonalBest ? deliveryConfig.speedrunPBMessage() : deliveryConfig.speedrunMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(Utils.getPlayerName(client)))
            .replacement("%QUEST%", Replacements.ofWiki(questName))
            .replacement("%TIME%", Replacements.ofText(duration))
            .replacement("%BEST%", Replacements.ofText(pb))
            .build();
        return NotificationBody.builder()
            .text(notifyMessage)
            .extra(extra)
            .type(NotificationType.SPEEDRUN)
            .build();
    }

    public void onGameMessage(String chatMessage) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (!enabled) {
            return;
        }

        if (chatMessage.startsWith("Speedrun duration: ")) {
            isPersonalBest = chatMessage.endsWith(" (new personal best)");
        }
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifySpeedrun()
            && profileEligibilityService.isEligible(profile, false, false, true);
    }
}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.SettingsManager;
import pigeon.domain.SeasonalPolicy;
import pigeon.message.DiscordMessageHandler;
import pigeon.message.NotificationBody;
import pigeon.util.AccountTypeTracker;
import pigeon.util.Utils;
import pigeon.util.WorldTypeTracker;
import pigeon.util.WorldUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.apache.commons.lang3.StringUtils;

import javax.inject.Inject;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
public abstract class BaseNotifier {

    @Inject
    protected PigeonConfig config;

    @Inject
    protected AccountTypeTracker accountTracker;

    @Inject
    protected WorldTypeTracker worldTracker;

    @Inject
    protected Client client;

    @Inject
    protected EventBus eventBus;

    @Inject
    protected ScheduledExecutorService executor;

    @Inject
    protected DiscordMessageHandler messageHandler;

    public boolean isEnabled() {
        return worldTracker.hasValidState() && accountTracker.hasValidState();
    }

    protected abstract String getWebhookUrl();

    protected final void createMessage(boolean sendImage, NotificationBody<?> body) {
        this.createMessage(getWebhookUrl(), sendImage, body);
    }

    protected final void createMessage(String overrideUrl, boolean sendImage, NotificationBody<?> body) {
        // Preserve Dink's legacy behavior of invoking the handler even for a blank URL.
        messageHandler.createMessage(resolveWebhook(config, overrideUrl), sendImage, body);
        publishPluginMessage(body);
    }

    protected final boolean deliver(PigeonConfig deliveryConfig, String overrideUrl, boolean sendImage,
                                    NotificationBody<?> body) {
        String url = resolveWebhook(deliveryConfig, overrideUrl);
        if (StringUtils.isBlank(url)) {
            return false;
        }

        messageHandler.createMessage(deliveryConfig, url, sendImage, body);
        return true;
    }

    private String resolveWebhook(PigeonConfig deliveryConfig, String overrideUrl) {
        String override;
        if (StringUtils.isNotBlank(deliveryConfig.leaguesWebhook())
            && deliveryConfig.seasonalPolicy() == SeasonalPolicy.FORWARD_TO_LEAGUES
            && WorldUtils.isSeasonal(client)) {
            override = deliveryConfig.leaguesWebhook();
        } else {
            override = overrideUrl;
        }
        return StringUtils.isNotBlank(override) ? override : deliveryConfig.primaryWebhook();
    }

    protected final void publishPluginMessage(NotificationBody<?> body) {
        // notify other hub plugins
        var playerName = body.getPlayerName() != null ? body.getPlayerName() : Utils.getPlayerName(client);
        var accountType = body.getAccountType() != null ? body.getAccountType() : Utils.getAccountType(client);
        executor.execute(() -> {
            Map<String, Object> metadata = body.getExtra() != null ? new HashMap<>(body.getExtra().sanitized()) : new HashMap<>();
            metadata.put("playerName", playerName);
            metadata.put("accountType", String.valueOf(accountType));
            metadata.put("plainText", body.getText().evaluate(false));
            var payload = new PluginMessage(SettingsManager.CONFIG_GROUP, body.getType().name(), Collections.unmodifiableMap(metadata));
            eventBus.post(payload);
        });
    }

}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.notifiers.data.SerializedItemStack;
import pigeon.notifiers.data.TradeNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import pigeon.util.ItemUtils;
import pigeon.util.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.annotations.VarCStr;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageCapture;
import net.runelite.client.util.QuantityFormatter;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Image;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;

@Slf4j
@Singleton
public class TradeNotifier extends BaseNotifier {
    @VisibleForTesting
    public static final String TRADE_ACCEPTED_MESSAGE = "Accepted trade.";
    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bclientscript%2Ctrade_partner_set%5D.cs2#L3">CS2 Reference</a>
     */
    @VisibleForTesting
    static final @VarCStr int TRADE_COUNTERPARTY_VAR = 357;

    @VisibleForTesting
    static final int INV_TRADE_OTHER = InventoryID.TRADEOFFER | 0x8000;

    @Inject
    private ClientThread clientThread;

    @Inject
    private DrawManager drawManager;

    @Inject
    private ImageCapture imageCapture;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    private final AtomicReference<Image> image = new AtomicReference<>();

    @Override
    public boolean isEnabled() {
        return config.notifyTrades() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.tradeWebhook();
    }

    public void reset() {
        image.lazySet(null);
    }

    public void onTradeMessage(String message) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
            : isEnabled();
        if (!TRADE_ACCEPTED_MESSAGE.equals(message) || !enabled) {
            this.reset();
            return;
        }

        ItemContainer tradeInv = client.getItemContainer(InventoryID.TRADEOFFER);
        ItemContainer otherInv = client.getItemContainer(INV_TRADE_OTHER);
        if (tradeInv == null && otherInv == null) {
            log.debug("Could not find traded items!");
            this.reset();
            return;
        }
        Item[] trade = tradeInv != null ? tradeInv.getItems() : new Item[0];
        Item[] other = otherInv != null ? otherInv.getItems() : new Item[0];
        long receiveValue = getTotalValue(other);
        long giveValue = getTotalValue(trade);
        if (!profiles.isProfilesConfigured() && receiveValue + giveValue < config.tradeMinValue()) {
            this.reset();
            return;
        }
        List<SerializedItemStack> received = getItems(other);
        List<SerializedItemStack> disbursed = getItems(trade);

        String localPlayer = client.getLocalPlayer().getName();
        String counterparty = Utils.sanitize(client.getVarcStrValue(TRADE_COUNTERPARTY_VAR));
        TradeNotificationData extra = new TradeNotificationData(
            counterparty, received, disbursed, receiveValue, giveValue);
        if (profiles.isProfilesConfigured()) {
            NotificationBody<?> outbound = null;
            for (PigeonProfileConfig profile : profiles.getEnabledProfiles()) {
                if (!isProfileEnabled(profile)
                    || receiveValue + giveValue < profile.tradeMinValue()) continue;
                NotificationBody<?> body = createBody(
                    profile, localPlayer, counterparty, receiveValue, giveValue, extra);
                if (deliver(profile, profile.tradeWebhook(), profile.tradeSendImage(), body)
                    && outbound == null) outbound = body;
            }
            if (outbound != null) publishPluginMessage(outbound);
            reset();
            return;
        }

        createMessage(config.tradeSendImage(), createBody(
            config, localPlayer, counterparty, receiveValue, giveValue, extra));
        this.reset();
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, String localPlayer,
                                            String counterparty, long receiveValue, long giveValue,
                                            TradeNotificationData extra) {
        Template content = Template.builder()
            .template(deliveryConfig.tradeNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(localPlayer))
            .replacement("%COUNTERPARTY%", Replacements.ofLink(
                counterparty, deliveryConfig.playerLookupService().getPlayerUrl(counterparty)))
            .replacement("%IN_VALUE%", Replacements.ofText(QuantityFormatter.quantityToStackSize(receiveValue)))
            .replacement("%OUT_VALUE%", Replacements.ofText(QuantityFormatter.quantityToStackSize(giveValue)))
            .build();

        return NotificationBody.builder()
            .text(content)
            .extra(extra)
            .playerName(localPlayer)
            .screenshotOverride(image.get())
            .type(NotificationType.TRADE)
            .build();
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyTrades() && profileEligibilityService.isEligible(profile);
    }

    public void onWidgetLoad(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.TRADECONFIRM) {
            Utils.captureScreenshot(client, clientThread, drawManager, imageCapture, executor, config, image::set);
        }
    }

    public void onWidgetClose(WidgetClosed event) {
        // relevant when local player declines a trade since no chat message occurs
        if (event.getGroupId() == InterfaceID.TRADECONFIRM) {
            clientThread.invokeAtTickEnd(this::reset);
        }
    }

    private long getTotalValue(Item[] items) {
        long v = 0;
        for (Item item : items) {
            v += ItemUtils.getPrice(itemManager, item.getId()) * item.getQuantity();
        }
        return v;
    }

    private List<SerializedItemStack> getItems(Item[] items) {
        if (items.length == 0) {
            return Collections.emptyList();
        }
        Map<Integer, Integer> quantityById = new HashMap<>(items.length * 4 / 3);
        for (Item item : items) {
            quantityById.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        List<SerializedItemStack> stacks = new ArrayList<>(quantityById.size());
        quantityById.forEach((id, quantity) -> stacks.add(ItemUtils.stackFromItem(itemManager, id, quantity)));
        return stacks;
    }
}

package pigeon.notifiers;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import pigeon.message.Embed;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.notifiers.data.GrandExchangeNotificationData;
import pigeon.notifiers.data.SerializedItemStack;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import pigeon.util.ConfigUtil;
import pigeon.util.ItemUtils;
import pigeon.util.SerializedOffer;
import pigeon.util.Utils;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.grandexchange.GrandExchangePlugin;

import javax.inject.Inject;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

@Slf4j
public class GrandExchangeNotifier extends BaseNotifier {
    private static final Set<Integer> TAX_EXEMPT_ITEMS;
    private static final int LOGIN_DELAY = 2;
    private static final String RL_GE_PLUGIN_NAME = GrandExchangePlugin.class.getSimpleName().toLowerCase();
    private final AtomicInteger initTicks = new AtomicInteger();
    private static final String LEGACY_PROFILE_KEY = "legacy";
    private final Map<Integer, Map<String, Instant>> progressNotificationTimeBySlot = new HashMap<>();

    @Inject
    private ClientThread clientThread;

    @Inject
    private Gson gson;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    @Override
    public boolean isEnabled() {
        return config.notifyGrandExchange() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.grandExchangeWebhook();
    }

    public void onAccountChange() {
        progressNotificationTimeBySlot.clear();
    }

    public void onGameStateChange(GameStateChanged event) {
        if (event.getGameState() != GameState.LOGGED_IN)
            initTicks.set(LOGIN_DELAY);
    }

    public void onTick() {
        initTicks.updateAndGet(i -> Math.max(i - 1, 0));
    }

    public void onOfferChange(int slot, GrandExchangeOffer offer) {
        boolean loginReplay = initTicks.get() > 0;
        if (shouldHandle(slot, offer, loginReplay)) {
            clientThread.invoke(() -> {
                if (initTicks.get() > 0) {
                    return false; // retry later
                }

                ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
                boolean enabled = profiles.isProfilesConfigured()
                    ? profiles.getEnabledProfiles().stream().anyMatch(this::isProfileEnabled)
                    : isEnabled();
                if (!enabled) {
                    return true; // terminate execution since notifier is disabled
                }

                var welcome = client.getWidget(InterfaceID.WelcomeScreen.CONTENT);
                if (welcome != null && !welcome.isHidden()) {
                    return false; // wait until user has passed welcome screen
                }

                handleNotify(slot, offer, profiles, loginReplay);
                return true;
            });
        }
    }

    private void handleNotify(int slot, GrandExchangeOffer offer, ProfileRuntimeSnapshot profiles,
                              boolean loginReplay) {
        log.debug("Notifying for slot={}, item={}, quantity={}, targetPrice={}, spent={}, state={}",
            slot, offer.getItemId(), offer.getQuantitySold(), offer.getPrice(), offer.getSpent(), offer.getState());

        if (profiles.isProfilesConfigured()) {
            List<PigeonProfileConfig> recipients = profiles.getEnabledProfiles().stream()
                .filter(this::isProfileEnabled)
                .filter(profile -> shouldNotify(slot, offer, profile,
                    profile.getProfile().getId().toString(), loginReplay))
                .collect(java.util.stream.Collectors.toList());
            if (recipients.isEmpty()) return;

            OfferDetails details = getOfferDetails(slot, offer);
            NotificationBody<?> outbound = null;
            for (PigeonProfileConfig profile : recipients) {
                NotificationBody<?> body = createBody(profile, offer, details);
                if (deliver(profile, profile.grandExchangeWebhook(),
                    profile.grandExchangeSendImage(), body) && outbound == null) outbound = body;
            }
            if (outbound != null) publishPluginMessage(outbound);
            return;
        }

        if (shouldNotify(slot, offer, config, LEGACY_PROFILE_KEY, loginReplay)) {
            createMessage(config.grandExchangeSendImage(), createBody(config, offer, getOfferDetails(slot, offer)));
        }
    }

    private OfferDetails getOfferDetails(int slot, GrandExchangeOffer offer) {

        ItemComposition comp = itemManager.getItemComposition(offer.getItemId());
        SerializedItemStack item = new SerializedItemStack(offer.getItemId(), offer.getQuantitySold(), getUnitPrice(offer), comp.getMembersName());
        long marketPrice = ItemUtils.getPrice(itemManager, offer.getItemId());
        OfferType type = getType(offer.getState());
        Long tax = type == OfferType.SELL ? calculateTax(item.getPriceEach(), item.getQuantity(), item.getId()) : null;

        return new OfferDetails(slot, item, marketPrice, type, tax);
    }

    private NotificationBody<?> createBody(pigeon.PigeonConfig deliveryConfig, GrandExchangeOffer offer,
                                            OfferDetails details) {
        List<Embed> embeds;
        if (deliveryConfig.grandExchangeSendImage() || !deliveryConfig.discordRichEmbeds()) {
            embeds = Collections.emptyList();
        } else {
            embeds = ItemUtils.buildEmbeds(new int[] { offer.getItemId() });
        }

        String playerName = Utils.getPlayerName(client);
        Template message = Template.builder()
            .template(deliveryConfig.grandExchangeNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(playerName))
            .replacement("%TYPE%", Replacements.ofText(details.type.getDisplayName()))
            .replacement("%ITEM%", ItemUtils.templateStack(details.item, true))
            .replacement("%STATUS%", Replacements.ofText(getHumanStatus(offer.getState())))
            .build();
        return NotificationBody.builder()
            .type(NotificationType.GRAND_EXCHANGE)
            .text(message)
            .embeds(embeds)
            .extra(new GrandExchangeNotificationData(details.slot + 1, offer.getState(), details.item,
                details.marketPrice, offer.getPrice(), offer.getTotalQuantity(), details.tax))
            .playerName(playerName)
            .build();
    }

    private boolean shouldHandle(int slot, GrandExchangeOffer offer, boolean justLogged) {
        // During login, we only care about offers that have been completed, and that were *not* observed by the RuneLite GE plugin
        // This makes sure we don't fire any duplicate notifications for offers that were finished while we were online
        if (justLogged) {
            // check if offer is a completion
            if (offer.getState() != GrandExchangeOfferState.BOUGHT && offer.getState() != GrandExchangeOfferState.SOLD)
                return false;

            // require GE plugin to be enabled so that observed trades are written to config
            // however: not bullet-proof since GE plugin could've been disabled during the initial trade completion
            if (ConfigUtil.isPluginDisabled(configManager, RL_GE_PLUGIN_NAME))
                return false;

            // check whether the completion has already been observed
            if (getSavedOffer(slot).filter(saved -> saved.equalsOffer(offer)).isPresent())
                return false;
        }

        return true;
    }

    private boolean shouldNotify(int slot, GrandExchangeOffer offer, pigeon.PigeonConfig deliveryConfig,
                                 String profileKey, boolean loginReplay) {
        if (!loginReplay && deliveryConfig instanceof PigeonProfileConfig
            && !isProfileEnabled((PigeonProfileConfig) deliveryConfig)) return false;
        if (!loginReplay && deliveryConfig == config && !isEnabled()) return false;

        boolean valuable = getTransactedValue(offer) >= deliveryConfig.grandExchangeMinValue();

        switch (offer.getState()) {
            case EMPTY:
                if (client.getGameState() == GameState.LOGGED_IN)
                    progressNotificationTimeBySlot.remove(slot);
                return false;

            case BOUGHT:
            case SOLD:
                progressNotificationTimeBySlot.remove(slot);
                return valuable;

            case CANCELLED_BUY:
            case CANCELLED_SELL:
                progressNotificationTimeBySlot.remove(slot);
                return valuable && deliveryConfig.grandExchangeIncludeCancelled();

            case BUYING:
            case SELLING:
                if (!valuable || offer.getQuantitySold() <= 0)
                    return false;

                if (offer.getQuantitySold() >= offer.getTotalQuantity())
                    return false; // ignore since BOUGHT/SOLD is about to occur

                int spacing = deliveryConfig.grandExchangeProgressSpacingMinutes();
                if (spacing < 0)
                    return false; // negative => no in-progress notifications allowed

                if (getSavedOffer(slot).filter(saved -> saved.equalsOffer(offer)).isPresent())
                    return false; // ignore since quantity already observed (relevant when trade limit is binding)

                // convert minutes to seconds, but treat 0 minutes as 2 seconds to workaround duplicate RL events
                long spacingSeconds = spacing > 0 ? spacing * 60L : 2L;

                Instant now = Instant.now();
                Map<String, Instant> times = progressNotificationTimeBySlot.computeIfAbsent(
                    slot, ignored -> new HashMap<>());
                Instant prior = times.get(profileKey);
                if (prior == null || Duration.between(prior, now).getSeconds() >= spacingSeconds) {
                    return times.put(profileKey, now) == prior;
                }
                return false;

            default:
                return false;
        }
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyGrandExchange() && profileEligibilityService.isEligible(profile);
    }

    @lombok.Value
    private static class OfferDetails {
        int slot;
        SerializedItemStack item;
        long marketPrice;
        OfferType type;
        Long tax;
    }

    private Optional<SerializedOffer> getSavedOffer(int slot) {
        return Optional.ofNullable(configManager.getRSProfileConfiguration("geoffer", String.valueOf(slot)))
            .map(json -> {
                try {
                    return gson.fromJson(json, SerializedOffer.class);
                } catch (JsonSyntaxException e) {
                    log.warn("Failed to read saved GE offer", e);
                    return null;
                }
            });
    }

    public static String getHumanStatus(GrandExchangeOfferState state) {
        switch (state) {
            case CANCELLED_BUY:
            case CANCELLED_SELL:
                return "Cancelled";

            case BUYING:
            case SELLING:
                return "In Progress";

            case BOUGHT:
            case SOLD:
                return "Completed";

            default:
                return null;
        }
    }

    private static OfferType getType(GrandExchangeOfferState state) {
        switch (state) {
            case BUYING:
            case CANCELLED_BUY:
            case BOUGHT:
                return OfferType.BUY;

            case SELLING:
            case CANCELLED_SELL:
            case SOLD:
                return OfferType.SELL;

            default:
                return null;
        }
    }

    private static long getTransactedValue(GrandExchangeOffer offer) {
        long spent = offer.getSpent();
        return spent > 0 ? spent : (long) offer.getQuantitySold() * offer.getPrice();
    }

    private static int getUnitPrice(GrandExchangeOffer offer) {
        int quantity = offer.getQuantitySold();
        int spent = offer.getSpent();
        return quantity > 0 && spent > 0 ? spent / quantity : offer.getPrice();
    }

    private static long calculateTax(int unitPrice, int quantity, int itemId) {
        // https://secure.runescape.com/m=news/grand-exchange-tax--item-sink?oldschool=1
        if (unitPrice < 50 || TAX_EXEMPT_ITEMS.contains(itemId)) {
            return 0L;
        }
        int price = Math.min(unitPrice, 250_000_000);
        int unitTax = (int) Math.floor(price * 0.02);
        return (long) unitTax * quantity;
    }

    @Getter
    @RequiredArgsConstructor
    private enum OfferType {
        BUY("bought"),
        SELL("sold");

        private final String displayName;
    }

    static {
        // https://oldschool.runescape.wiki/w/Category:Items_exempt_from_Grand_Exchange_tax
        TAX_EXEMPT_ITEMS = ImmutableSet.of(
            ItemID.CHISEL, ItemID.DIBBER, ItemID.GARDENING_TROWEL,
            ItemID.GLASSBLOWINGPIPE, ItemID.HAMMER, ItemID.NEEDLE,
            ItemID.PESTLE_AND_MORTAR, ItemID.RAKE, ItemID.POH_SAW,
            ItemID.SECATEURS, ItemID.SHEARS, ItemID.SPADE,
            ItemID.WATERING_CAN_0, ItemID.OSRS_BOND
        );
    }
}

package pigeon.notifiers;

import pigeon.PigeonConfig;
import pigeon.domain.ChatNotificationType;
import pigeon.message.NotificationBody;
import pigeon.message.NotificationType;
import pigeon.message.templating.Replacements;
import pigeon.message.templating.Template;
import pigeon.notifiers.data.ChatNotificationData;
import pigeon.profiles.PigeonProfileConfig;
import pigeon.profiles.ProfileEligibilityService;
import pigeon.profiles.ProfileRuntimeService;
import pigeon.profiles.ProfileRuntimeSnapshot;
import pigeon.util.Utils;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanID;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.NotificationFired;
import net.runelite.client.util.Text;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Objects;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

import static pigeon.domain.ChatNotificationType.*;

@Singleton
public class ChatNotifier extends BaseNotifier {
    public static final String PATTERNS_CONFIG_KEY = "chatPatterns";

    @Inject
    private ClientThread clientThread;

    @Inject
    private ProfileRuntimeService profileRuntimeService;

    @Inject
    private ProfileEligibilityService profileEligibilityService;

    private final Collection<Pattern> regexps = new ArrayList<>();
    private volatile boolean dirty;

    @Override
    public boolean isEnabled() {
        return config.notifyChat() && super.isEnabled();
    }

    @Override
    protected String getWebhookUrl() {
        return config.chatWebhook();
    }

    public void init() {
        this.dirty = true;
    }

    public void reset() {
        this.dirty = true;
        clientThread.invoke(() -> {
            if (dirty) {
                regexps.clear();
            }
        });
    }

    public void onConfig(String key) {
        if (PATTERNS_CONFIG_KEY.equals(key)) {
            this.dirty = true;
        }
    }

    public void onTick() {
        if (this.dirty) {
            var username = Utils.getPlayerName(client);
            if (username == null || username.isEmpty()) {
                return;
            }
            this.dirty = false;
            this.loadPatterns(username);
        }
    }

    public void onMessage(@NotNull ChatMessageType messageType, @Nullable String source, @NotNull String message) {
        ChatNotificationType type = ChatNotificationType.MAPPINGS.get(messageType);
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = type != null && (profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(profile -> isProfileEnabled(profile)
                && profile.chatMessageTypes().contains(type))
            : config.chatMessageTypes().contains(type) && isEnabled());
        if (enabled) {
            clientThread.invoke(() -> {
                if (!profiles.isProfilesConfigured() && dirty)
                    return false; // try later

                String cleanSource = source != null ? Text.sanitize(source) : null;
                this.handleNotify(profiles, type, messageType, cleanSource, message);
                return true;
            });
        }
    }

    public void onCommand(CommandExecuted event) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(profile -> isProfileEnabled(profile)
                && profile.chatMessageTypes().contains(COMMAND))
            : config.chatMessageTypes().contains(COMMAND) && isEnabled();
        if (enabled) {
            String fullMessage = join(event);
            clientThread.invoke(() -> {
                if (!profiles.isProfilesConfigured() && dirty)
                    return false; // try later

                this.handleNotify(profiles, COMMAND, ChatMessageType.UNKNOWN, "CommandExecuted", fullMessage);
                return true;
            });
        }
    }

    public void onNotification(NotificationFired event) {
        ProfileRuntimeSnapshot profiles = profileRuntimeService.snapshot();
        boolean gameMessage = event.getNotification().isGameMessage()
            && client.getGameState() == GameState.LOGGED_IN;
        if (!profiles.isProfilesConfigured() && gameMessage && config.chatMessageTypes().contains(GAME)) return;
        boolean enabled = profiles.isProfilesConfigured()
            ? profiles.getEnabledProfiles().stream().anyMatch(profile -> isProfileEnabled(profile)
                && profile.chatMessageTypes().contains(RUNELITE)
                && !(gameMessage && profile.chatMessageTypes().contains(GAME)))
            : config.chatMessageTypes().contains(RUNELITE) && isEnabled();
        if (enabled) {
            clientThread.invoke(() -> {
                if (!profiles.isProfilesConfigured() && dirty)
                    return false; // try later

                this.handleNotify(profiles, RUNELITE, ChatMessageType.UNKNOWN,
                    "NotificationFired", event.getMessage(), profile ->
                        !(gameMessage && profile.chatMessageTypes().contains(GAME)));
                return true;
            });
        }
    }

    private void handleNotify(ProfileRuntimeSnapshot profiles, ChatNotificationType notificationType,
                              ChatMessageType type, String source, String message) {
        handleNotify(profiles, notificationType, type, source, message, profile -> true);
    }

    private void handleNotify(ProfileRuntimeSnapshot profiles, ChatNotificationType notificationType,
                              ChatMessageType type, String source, String message,
                              java.util.function.Predicate<PigeonProfileConfig> extraFilter) {
        if (profiles.isProfilesConfigured()) {
            String username = Utils.getPlayerName(client);
            List<PigeonProfileConfig> recipients = profiles.getEnabledProfiles().stream()
                .filter(this::isProfileEnabled)
                .filter(profile -> profile.chatMessageTypes().contains(notificationType))
                .filter(extraFilter)
                .filter(profile -> hasMatch(profile.chatPatterns(), username, message))
                .collect(Collectors.toList());
            if (recipients.isEmpty()) return;
            var clanTitle = getClanTitle(type, source, message);
            ChatNotificationData extra = new ChatNotificationData(type, source, clanTitle, message);
            NotificationBody<?> outbound = null;
            for (PigeonProfileConfig profile : recipients) {
                NotificationBody<?> body = createBody(profile, notificationType, source, message, username, extra);
                if (deliver(profile, profile.chatWebhook(), profile.chatSendImage(), body)
                    && outbound == null) outbound = body;
            }
            if (outbound != null) publishPluginMessage(outbound);
            return;
        }
        if (!hasMatch(message)) return;
        var clanTitle = getClanTitle(type, source, message);
        String playerName = Utils.getPlayerName(client);
        createMessage(config.chatSendImage(), createBody(config, notificationType, source, message,
            playerName, new ChatNotificationData(type, source, clanTitle, message)));
    }

    private NotificationBody<?> createBody(PigeonConfig deliveryConfig, ChatNotificationType notificationType,
                                            String source, String message, String playerName,
                                            ChatNotificationData extra) {
        Template template = Template.builder()
            .template(deliveryConfig.chatNotifyMessage())
            .replacementBoundary("%")
            .replacement("%USERNAME%", Replacements.ofText(playerName))
            .replacement("%MESSAGE%", Replacements.ofText(message))
            .replacement("%SENDER%", Replacements.ofText(getSender(notificationType, source)))
            .build();
        return NotificationBody.builder()
            .text(template)
            .type(NotificationType.CHAT)
            .extra(extra)
            .playerName(playerName)
            .build();
    }

    private boolean hasMatch(String chatMessage) {
        for (Pattern pattern : regexps) {
            if (pattern.matcher(chatMessage).find())
                return true;
        }
        return false;
    }

    private boolean hasMatch(String patterns, String username, String chatMessage) {
        return patterns.lines().map(String::trim).filter(s -> !s.isEmpty())
            .map(s -> s.replace("%USERNAME%", username))
            .map(Utils::regexify).filter(Objects::nonNull)
            .anyMatch(pattern -> pattern.matcher(chatMessage).find());
    }

    private boolean isProfileEnabled(PigeonProfileConfig profile) {
        return profile.notifyChat() && profileEligibilityService.isEligible(profile);
    }

    private void loadPatterns(String username) {
        regexps.clear();
        regexps.addAll(
            config.chatPatterns().lines()
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .map(s -> s.replace("%USERNAME%", username))
                .map(Utils::regexify)
                .filter(Objects::nonNull)
                .collect(Collectors.toList())
        );
    }

    @Nullable
    private ClanTitle getClanTitle(@NotNull ChatMessageType type, @Nullable String source, @NotNull String message) {
        if (type == ChatMessageType.CLAN_MESSAGE && message.endsWith(" has joined.")) {
            String name = message.substring(0, message.length() - " has joined.".length());
            var title = getClanTitle(ChatMessageType.CLAN_CHAT, name);
            return title != null ? title : getClanTitle(ChatMessageType.CLAN_GUEST_CHAT, name);
        }
        return getClanTitle(type, source);
    }

    @Nullable
    private ClanTitle getClanTitle(@NotNull ChatMessageType type, @Nullable String name) {
        if (name == null) return null;

        ClanChannel channel;
        ClanSettings settings;
        if (type == ChatMessageType.CLAN_CHAT) {
            channel = client.getClanChannel();
            settings = client.getClanSettings();
        } else if (type == ChatMessageType.CLAN_GUEST_CHAT) {
            channel = client.getGuestClanChannel();
            settings = client.getGuestClanSettings();
        } else if (type == ChatMessageType.CLAN_GIM_CHAT) {
            channel = client.getClanChannel(ClanID.GROUP_IRONMAN);
            settings = client.getClanSettings(ClanID.GROUP_IRONMAN);
        } else {
            channel = null;
            settings = null;
        }

        ClanChannelMember member;
        if (channel == null || settings == null || (member = channel.findMember(name)) == null) {
            return null;
        }
        return settings.titleForRank(member.getRank());
    }

    private static String getSender(ChatNotificationType type, String source) {
		if (source == null || source.isEmpty() || type == COMMAND || type == RUNELITE) {
			return "[" + type + "]";
		}
		return source;
    }

    private static String join(CommandExecuted event) {
        StringBuilder sb = new StringBuilder();
        sb.append("::").append(event.getCommand());

        String[] args = event.getArguments();
        if (args != null) {
            for (String arg : args) {
                sb.append(' ').append(arg);
            }
        }
        return sb.toString();
    }
}

